import * as THREE from 'three'

export const clamp = (v, a, b) => Math.max(a, Math.min(b, v))
export const lerp = (a, b, t) => a + (b - a) * t
export const invLerp = (a, b, v) => clamp((v - a) / (b - a), 0, 1)
export const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt))
export const mod = (n, m) => ((n % m) + m) % m
export const TAU = Math.PI * 2

export function smoothstep(edge0, edge1, x) {
  const t = clamp((x - edge0) / (edge1 - edge0), 0, 1)
  return t * t * (3 - 2 * t)
}

export function angleLerp(a, b, t) {
  let d = mod(b - a + Math.PI, TAU) - Math.PI
  return a + d * t
}

export function angleDelta(a, b) {
  return mod(b - a + Math.PI, TAU) - Math.PI
}

export function hash2(x, y) {
  let h = x * 374761393 + y * 668265263
  h = (h ^ (h >> 13)) * 1274126177
  h = h ^ (h >> 16)
  return (h >>> 0) / 4294967295
}

function smoothNoise(x, y) {
  const ix = Math.floor(x), iy = Math.floor(y)
  const fx = x - ix, fy = y - iy
  const ux = fx * fx * (3 - 2 * fx)
  const uy = fy * fy * (3 - 2 * fy)
  const a = hash2(ix, iy), b = hash2(ix + 1, iy)
  const c = hash2(ix, iy + 1), d = hash2(ix + 1, iy + 1)
  return lerp(lerp(a, b, ux), lerp(c, d, ux), uy)
}

export function noise2(x, y) {
  let value = 0, amp = 0.5, freq = 1
  for (let i = 0; i < 4; i++) {
    value += smoothNoise(x * freq, y * freq) * amp
    amp *= 0.5
    freq *= 2.02
  }
  return value
}

export function fbm(x, y, octaves = 4) {
  let value = 0, amp = 0.5, freq = 1, norm = 0
  for (let i = 0; i < octaves; i++) {
    value += smoothNoise(x * freq, y * freq) * amp
    norm += amp
    amp *= 0.5
    freq *= 2.03
  }
  return value / norm
}

export function mulberry32(seed) {
  let a = seed >>> 0
  return function () {
    a |= 0
    a = (a + 0x6D2B79F5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

export function range(rng, a, b) { return a + (b - a) * rng() }

export function pick(rng, arr) { return arr[Math.floor(rng() * arr.length)] }

export function dist2D(ax, az, bx, bz) {
  return Math.hypot(ax - bx, az - bz)
}

export function radialTexture(inner = 'rgba(255,255,255,1)', outer = 'rgba(255,255,255,0)', size = 128, stops = null) {
  const canvas = document.createElement('canvas')
  canvas.width = canvas.height = size
  const ctx = canvas.getContext('2d')
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2)
  if (stops) stops.forEach(([p, c]) => g.addColorStop(p, c))
  else { g.addColorStop(0, inner); g.addColorStop(0.45, inner); g.addColorStop(1, outer) }
  ctx.fillStyle = g
  ctx.fillRect(0, 0, size, size)
  const tex = new THREE.CanvasTexture(canvas)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

export function grainTexture(size = 256, repeat = 50, strength = 26) {
  const canvas = document.createElement('canvas')
  canvas.width = canvas.height = size
  const ctx = canvas.getContext('2d')
  const img = ctx.createImageData(size, size)
  for (let i = 0; i < size * size; i++) {
    const n = 128 + (Math.random() - 0.5) * strength * 2
    img.data[i * 4] = n
    img.data[i * 4 + 1] = n
    img.data[i * 4 + 2] = n
    img.data[i * 4 + 3] = 255
  }
  ctx.putImageData(img, 0, 0)
  const tex = new THREE.CanvasTexture(canvas)
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping
  tex.repeat.set(repeat, repeat)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

export function cloudTexture() {
  const size = 256
  const canvas = document.createElement('canvas')
  canvas.width = size; canvas.height = size
  const ctx = canvas.getContext('2d')
  ctx.clearRect(0, 0, size, size)
  for (let i = 0; i < 26; i++) {
    const x = size * 0.5 + (Math.random() - 0.5) * size * 0.72
    const y = size * 0.55 + (Math.random() - 0.5) * size * 0.3
    const r = size * (0.08 + Math.random() * 0.18)
    const g = ctx.createRadialGradient(x, y, 0, x, y, r)
    g.addColorStop(0, 'rgba(255,244,224,0.42)')
    g.addColorStop(0.6, 'rgba(255,238,214,0.18)')
    g.addColorStop(1, 'rgba(255,238,214,0)')
    ctx.fillStyle = g
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); ctx.fill()
  }
  const tex = new THREE.CanvasTexture(canvas)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

export function leafTexture() {
  const size = 128
  const canvas = document.createElement('canvas')
  canvas.width = size; canvas.height = size
  const ctx = canvas.getContext('2d')
  ctx.clearRect(0, 0, size, size)
  ctx.fillStyle = '#fff'
  for (let i = 0; i < 12; i++) {
    const x = 24 + Math.random() * 80
    const y = 10 + Math.random() * 34
    ctx.save()
    ctx.translate(x, y)
    ctx.rotate((Math.random() - 0.5) * 0.9)
    ctx.beginPath()
    ctx.ellipse(0, 0, 3.5, 17 + Math.random() * 10, 0, 0, TAU)
    ctx.fill()
    ctx.restore()
  }
  const tex = new THREE.CanvasTexture(canvas)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

export function makeMat(color, opts = {}) {
  return new THREE.MeshStandardMaterial({ color, roughness: 0.82, metalness: 0.02, flatShading: true, ...opts })
}

export function mesh(geo, mat, x = 0, y = 0, z = 0) {
  const m = new THREE.Mesh(geo, mat)
  m.position.set(x, y, z)
  return m
}

export function capsule(r, len, seg = 5) {
  return new THREE.CapsuleGeometry(r, len, seg, seg * 2)
}

export function sphere(r, seg = 10, detail = 0) {
  return new THREE.SphereGeometry(r, seg, Math.max(4, Math.floor(seg * 0.7)))
}

export function circleSprite(color, size = 1, opacity = 1) {
  const tex = radialTexture('rgba(255,255,255,1)', 'rgba(255,255,255,0)', 128, [
    [0, 'rgba(255,255,255,1)'], [0.25, 'rgba(255,255,255,.9)'], [0.55, 'rgba(255,255,255,.25)'], [1, 'rgba(255,255,255,0)'],
  ])
  const mat = new THREE.SpriteMaterial({ map: tex, color, blending: THREE.AdditiveBlending, transparent: true, opacity, depthWrite: false })
  const sprite = new THREE.Sprite(mat)
  sprite.scale.setScalar(size)
  return sprite
}

export function glowSprite(color, size = 2, opacity = 0.8) {
  return circleSprite(color, size, opacity)
}

export function formatTime(seconds) {
  const m = Math.floor(seconds / 60)
  const s = Math.floor(seconds % 60)
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`
}

export function canvasPortrait(renderer, sceneFactory, size = 192) {
  const renderer2 = new THREE.WebGLRenderer({ antialias: true, alpha: true, preserveDrawingBuffer: true })
  renderer2.setSize(size, size)
  renderer2.setPixelRatio(1)
  renderer2.outputColorSpace = THREE.SRGBColorSpace
  renderer2.toneMapping = THREE.ACESFilmicToneMapping
  renderer2.toneMappingExposure = 1.15
  renderer2.setClearColor(0x000000, 0)
  const scene = new THREE.Scene()
  const camera = new THREE.PerspectiveCamera(30, 1, 0.1, 100)
  scene.add(new THREE.HemisphereLight(0xcfe9ff, 0x203a2c, 2.2))
  const key = new THREE.DirectionalLight(0xffdca8, 3.2)
  key.position.set(3, 5, 4)
  scene.add(key)
  const rim = new THREE.DirectionalLight(0x5fffd0, 2)
  rim.position.set(-4, 2, -4)
  scene.add(rim)
  const obj = sceneFactory()
  scene.add(obj)
  const box = new THREE.Box3().setFromObject(obj)
  const center = box.getCenter(new THREE.Vector3())
  const sphereBox = box.getBoundingSphere(new THREE.Sphere())
  const radius = Math.max(0.4, sphereBox.radius)
  camera.position.set(center.x + radius * 1.55, center.y + radius * 0.7, center.z + radius * 2.3)
  camera.lookAt(center)
  camera.position.multiplyScalar(1)
  const dist = radius / Math.sin(THREE.MathUtils.degToRad(15))
  const dir = new THREE.Vector3(0.42, 0.28, 1).normalize()
  camera.position.copy(center).addScaledVector(dir, dist)
  camera.lookAt(center)
  renderer2.render(scene, camera)
  const data = renderer2.domElement.toDataURL('image/png')
  renderer2.dispose()
  scene.traverse(o => { if (o.geometry) o.geometry.dispose?.() })
  return data
}

import { clamp, fbm, lerp, smoothstep, noise2 } from './utils.js'

export const ISLAND_RADIUS = 128
export const SEA_LEVEL = 0

export const PATH_MAIN = [
  [8, 92], [12, 78], [18, 62], [25, 48], [28, 36], [21, 24], [8, 14], [-8, 6], [-22, -2], [-31, -9], [-40, -17], [-47, -25],
]
export const PATH_GROVE = [
  [28, 36], [24, 22], [20, 8], [14, -8], [9, -24], [5, -38], [1, -52], [-1, -61],
]
export const PATH_REEF = [
  [25, 48], [38, 45], [50, 40], [58, 31], [64, 20], [66, 10],
]

export const VILLAGE = { x: 28, z: 36, r: 25, y: 5.2 }
export const WATERFALL = { x: -31, z: -9, y: 10.2 }
export const SHRINE_NIAN = { x: -47, z: -25, r: 13, y: 17.2 }
export const SHRINE_BAKUNAWA = { x: 66, z: 10, r: 12, y: 4.2 }
export const SHRINE_QUETZAL = { x: 6, z: -36, r: 12, y: 7.4 }
export const SILK_TREE = { x: -2, z: -64, r: 18, y: 6.8 }

function gauss(x, z, cx, cz, radius) {
  const d2 = (x - cx) ** 2 + (z - cz) ** 2
  return Math.exp(-d2 / (2 * radius * radius))
}

function flatten(h, x, z, spec) {
  const d = Math.hypot(x - spec.x, z - spec.z)
  const t = 1 - smoothstep(spec.r * 0.35, spec.r, d)
  return lerp(h, spec.y, t * 0.94)
}

/** Analytic island height. The terrain mesh and all gameplay share this. */
export function terrainHeight(x, z) {
  const r = Math.hypot(x * 0.97, z * 1.03)
  let profile
  if (r < 78) profile = 6.2
  else if (r < 98) profile = lerp(6.2, 2.8, smoothstep(78, 98, r))
  else if (r < 116) profile = lerp(2.8, 0.35, smoothstep(98, 116, r))
  else profile = lerp(0.35, -8, smoothstep(116, 138, r))

  const inland = 1 - smoothstep(74, 114, r)
  const rolls = (fbm(x * 0.021 + 13.1, z * 0.021 - 8.7, 4) - 0.48) * 6.4
  const detail = (noise2(x * 0.075 - 4, z * 0.075 + 2) - 0.5) * 1.1
  const mountain = gauss(x, z, -46, -24, 27) * 19 + gauss(x, z, -25, -9, 12) * 5.5
  const ridge = gauss(x, z, 17, -55, 24) * 6.5 + gauss(x, z, 55, 38, 15) * 2.4
  let h = profile + (rolls + detail + mountain + ridge) * inland

  // Broad sandy shelf around the island.
  const shore = smoothstep(91, 108, r) * (1 - smoothstep(112, 126, r))
  h = lerp(h, 1.15, shore * 0.32)

  h = flatten(h, x, z, VILLAGE)
  h = flatten(h, x, z, { ...WATERFALL, r: 9 })
  h = flatten(h, x, z, SHRINE_NIAN)
  h = flatten(h, x, z, SHRINE_BAKUNAWA)
  h = flatten(h, x, z, SHRINE_QUETZAL)
  h = flatten(h, x, z, SILK_TREE)
  return h
}

export function terrainNormal(x, z, eps = 0.7) {
  const hL = terrainHeight(x - eps, z)
  const hR = terrainHeight(x + eps, z)
  const hD = terrainHeight(x, z - eps)
  const hU = terrainHeight(x, z + eps)
  return new (Object.getPrototypeOf({}).constructor === Object ? Object : Object)(0)
}

export function getNormal(x, z) {
  const e = 0.8
  const hL = terrainHeight(x - e, z)
  const hR = terrainHeight(x + e, z)
  const hD = terrainHeight(x, z - e)
  const hU = terrainHeight(x, z + e)
  const nx = hL - hR
  const nz = hD - hU
  const ny = 2 * e
  const len = Math.hypot(nx, ny, nz) || 1
  return [nx / len, ny / len, nz / len]
}

export function slopeAt(x, z) {
  const [nx, ny, nz] = getNormal(x, z)
  return 1 - ny
}

export function isWater(x, z) {
  return terrainHeight(x, z) < 0.42
}

export function islandEdgeDistance(x, z) {
  return ISLAND_RADIUS - Math.hypot(x, z)
}

/** Sample a Catmull-Rom route and return evenly-ish spaced world points. */
export function samplePath(points, n = 180) {
  const out = []
  const p = (i) => points[clamp(i, 0, points.length - 1)]
  for (let i = 0; i < n; i++) {
    const t = (i / (n - 1)) * (points.length - 1)
    const seg = Math.floor(t)
    const u = t - seg
    const p0 = p(seg - 1), p1 = p(seg), p2 = p(seg + 1), p3 = p(seg + 2)
    const u2 = u * u, u3 = u2 * u
    const q = (a, b, c, d) => 0.5 * ((2 * b) + (-a + c) * u + (2 * a - 5 * b + 4 * c - d) * u2 + (-a + 3 * b - 3 * c + d) * u3)
    const x = q(p0[0], p1[0], p2[0], p3[0])
    const z = q(p0[1], p1[1], p2[1], p3[1])
    out.push([x, terrainHeight(x, z) + 0.06, z])
  }
  return out
}

export const ZONES = [
  { id: 'beach', name: 'PIMENTO BEACH', x: 8, z: 86, r: 30, color: '#e8c98f' },
  { id: 'village', name: 'NINE MILE VILLAGE', x: 28, z: 36, r: 27, color: '#f2a65a' },
  { id: 'mountain', name: 'BLUE MOUNTAIN RISE', x: -35, z: -12, r: 40, color: '#6a9a4f' },
  { id: 'grove', name: 'SILK COTTON GROVE', x: 2, z: -46, r: 32, color: '#2f6e50' },
  { id: 'reef', name: 'LUMINOUS REEF', x: 62, z: 20, r: 30, color: '#79dcff' },
]

export function zoneAt(x, z) {
  let best = ZONES[0], bd = Infinity
  for (const zone of ZONES) {
    const d = Math.hypot(x - zone.x, z - zone.z)
    if (d < zone.r && d < bd) { bd = d; best = zone }
  }
  return best
}

