const SKY_TOP = 0x2c7f9e
const SKY_HORIZON = 0xffc98e
const FOG_COLOR = 0x9fc9b3
const SUN_DIR = new THREE.Vector3(-0.55, 0.52, 0.42).normalize()

function colorMat(hex, opts = {}) {
  return new THREE.MeshStandardMaterial({ color: hex, roughness: 0.88, metalness: 0.02, ...opts })
}

function addMesh(parent, geo, mat, pos = [0, 0, 0], rot = [0, 0, 0], scale = [1, 1, 1]) {
  const m = new THREE.Mesh(geo, mat)
  m.position.set(...pos)
  m.rotation.set(...rot)
  m.scale.set(...scale)
  m.castShadow = true
  m.receiveShadow = true
  parent.add(m)
  return m
}

function mergeParts(parts) {
  const geos = []
  for (const p of parts) {
    const g = p.geo.clone()
    if (p.matrix) g.applyMatrix4(p.matrix)
    if (!g.attributes.uv) {
      g.setAttribute('uv', new THREE.BufferAttribute(new Float32Array(g.attributes.position.count * 2), 2))
    }
    const colors = new Float32Array(g.attributes.position.count * 3)
    const c = new THREE.Color(p.color ?? 0xffffff)
    for (let i = 0; i < g.attributes.position.count; i++) {
      colors[i * 3] = c.r; colors[i * 3 + 1] = c.g; colors[i * 3 + 2] = c.b
    }
    g.setAttribute('color', new THREE.BufferAttribute(colors, 3))
    geos.push(g)
  }
  const merged = mergeGeometries(geos, false)
  geos.forEach(g => g.dispose())
  return merged
}

function trs(pos = [0, 0, 0], rot = [0, 0, 0], scale = [1, 1, 1]) {
  return new THREE.Matrix4().compose(
    new THREE.Vector3(...pos),
    new THREE.Quaternion().setFromEuler(new THREE.Euler(...rot)),
    new THREE.Vector3(...scale),
  )
}

function terrainDetailTexture() {
  const size = 256
  const canvas = document.createElement('canvas')
  canvas.width = canvas.height = size
  const ctx = canvas.getContext('2d')
  const img = ctx.createImageData(size, size)
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const n = 210 + (noise2(x * 0.14, y * 0.14) - 0.5) * 54 + (Math.random() - 0.5) * 16
      const i = (y * size + x) * 4
      img.data[i] = n; img.data[i + 1] = n * 0.99; img.data[i + 2] = n * 0.93; img.data[i + 3] = 255
    }
  }
  ctx.putImageData(img, 0, 0)
  const tex = new THREE.CanvasTexture(canvas)
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping
  tex.repeat.set(110, 110)
  tex.colorSpace = THREE.SRGBColorSpace
  tex.anisotropy = 4
  return tex
}

function makeSignTexture(text, sub = '') {
  const canvas = document.createElement('canvas')
  canvas.width = 512; canvas.height = 192
  const ctx = canvas.getContext('2d')
  ctx.fillStyle = '#c99c5b'; ctx.fillRect(0, 0, 512, 192)
  ctx.strokeStyle = '#6d4a27'; ctx.lineWidth = 12; ctx.strokeRect(6, 6, 500, 180)
  ctx.strokeStyle = 'rgba(90,60,30,.35)'; ctx.lineWidth = 3
  for (let i = 0; i < 7; i++) { ctx.beginPath(); ctx.moveTo(0, 30 + i * 22); ctx.bezierCurveTo(160, 24 + i * 22, 320, 38 + i * 22, 512, 28 + i * 22); ctx.stroke() }
  ctx.fillStyle = '#3c2a16'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'
  ctx.font = '700 62px Georgia, serif'
  ctx.fillText(text, 256, sub ? 78 : 98)
  if (sub) { ctx.font = '600 22px Trebuchet MS, sans-serif'; ctx.fillStyle = 'rgba(60,42,22,.72)'; ctx.fillText(sub, 256, 142) }
  const tex = new THREE.CanvasTexture(canvas)
  tex.colorSpace = THREE.SRGBColorSpace
  tex.anisotropy = 4
  return tex
}

function makeStripeTexture(colors = ['#f5e6c8', '#d95f4f']) {
  const canvas = document.createElement('canvas')
  canvas.width = 256; canvas.height = 64
  const ctx = canvas.getContext('2d')
  const w = 32
  for (let i = 0; i < 8; i++) { ctx.fillStyle = colors[i % colors.length]; ctx.fillRect(i * w, 0, w, 64) }
  const tex = new THREE.CanvasTexture(canvas)
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping
  tex.repeat.set(1, 1)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

function makeCorrugatedTexture() {
  const canvas = document.createElement('canvas')
  canvas.width = 128; canvas.height = 128
  const ctx = canvas.getContext('2d')
  ctx.fillStyle = '#9ba4a8'; ctx.fillRect(0, 0, 128, 128)
  for (let x = 0; x < 128; x += 12) {
    const g = ctx.createLinearGradient(x, 0, x + 12, 0)
    g.addColorStop(0, 'rgba(255,255,255,.18)'); g.addColorStop(0.5, 'rgba(0,0,0,.12)'); g.addColorStop(1, 'rgba(255,255,255,.1)')
    ctx.fillStyle = g; ctx.fillRect(x, 0, 12, 128)
  }
  ctx.fillStyle = 'rgba(90,50,30,.12)'
  for (let i = 0; i < 14; i++) ctx.fillRect(Math.random() * 128, Math.random() * 128, 2 + Math.random() * 12, 1 + Math.random() * 2)
  const tex = new THREE.CanvasTexture(canvas)
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping
  tex.repeat.set(3, 1)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

function makeClothTexture(color) {
  const canvas = document.createElement('canvas')
  canvas.width = 64; canvas.height = 64
  const ctx = canvas.getContext('2d')
  ctx.fillStyle = color; ctx.fillRect(0, 0, 64, 64)
  ctx.fillStyle = 'rgba(255,255,255,.16)'
  for (let i = 0; i < 30; i++) ctx.fillRect(Math.random() * 64, Math.random() * 64, 2, 2)
  ctx.strokeStyle = 'rgba(0,0,0,.12)'
  for (let i = 0; i < 6; i++) { ctx.beginPath(); ctx.moveTo(0, i * 12); ctx.lineTo(64, i * 12 + 3); ctx.stroke() }
  const tex = new THREE.CanvasTexture(canvas)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

// ==================================================================== WORLD

export class World {
  constructor(scene, renderer, opts = {}) {
    this.scene = scene
    this.renderer = renderer
    this.root = new THREE.Group()
    scene.add(this.root)
    this.time = 0
    this.quality = opts.quality ?? 'high'
    this.rng = mulberry32(0x50a1)
    this.animated = []
    this.colliders = []
    this.shrines = {}
    this.waypoints = {}
    this.pickups = []
    this.npcModels = []
    this.waterfalls = []
    this.staticPaths = [...samplePath(PATH_MAIN, 170), ...samplePath(PATH_GROVE, 150), ...samplePath(PATH_REEF, 140)]
    this.pathSample = this.staticPaths.filter((_, i) => i % 5 === 0)

    scene.fog = new THREE.FogExp2(FOG_COLOR, 0.0031)
    this.buildSky()
    this.buildLights()
    this.buildTerrain()
    this.buildPaths()
    this.buildOcean()
    this.buildClouds()
    this.buildDistantLand()
    this.buildVegetation()
    this.buildRocks()
    this.buildVillage()
    this.buildBeachProps()
    this.buildWaterfall()
    this.buildShrines()
    this.buildSilkTree()
    this.buildNPCs()
    this.buildPickups()
    this.buildParticles()
    this.buildWaypoints()
  }

  // ------------------------------------------------------------------ SKY
  buildSky() {
    const geo = new THREE.SphereGeometry(480, 32, 20)
    const mat = new THREE.ShaderMaterial({
      side: THREE.BackSide, depthWrite: false, fog: false,
      uniforms: {
        topColor: { value: new THREE.Color(SKY_TOP) },
        horizonColor: { value: new THREE.Color(SKY_HORIZON) },
        sunColor: { value: new THREE.Color(0xfff2c9) },
        sunDir: { value: SUN_DIR.clone() },
        time: { value: 0 },
      },
      vertexShader: `
        varying vec3 vWorld;
        void main() {
          vWorld = normalize(position);
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        uniform vec3 topColor; uniform vec3 horizonColor; uniform vec3 sunColor; uniform vec3 sunDir; uniform float time;
        varying vec3 vWorld;
        void main() {
          float h = clamp(vWorld.y, -0.1, 1.0);
          float t = pow(max(h, 0.0), 0.48);
          vec3 col = mix(horizonColor, topColor, smoothstep(0.0, 0.8, t));
          vec3 dir = normalize(vWorld);
          float sun = pow(max(dot(dir, sunDir), 0.0), 220.0);
          float glow = pow(max(dot(dir, sunDir), 0.0), 7.0);
          col += sunColor * sun * 2.6;
          col += vec3(1.0, 0.63, 0.34) * glow * 0.28;
          float band = sin(dir.y * 22.0 + time * 0.02) * 0.5 + 0.5;
          col += vec3(1.0, 0.68, 0.45) * band * 0.018 * smoothstep(0.1, 0.6, dir.y);
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    })
    this.sky = new THREE.Mesh(geo, mat)
    this.sky.frustumCulled = false
    this.scene.add(this.sky)

    // Sun disc and glow.
    this.sun = glowSprite(0xfff0b8, 55, 0.95)
    this.sun.position.copy(SUN_DIR).multiplyScalar(360)
    this.sun.material.depthWrite = false
    this.scene.add(this.sun)
    this.sunGlow = glowSprite(0xffb36b, 190, 0.32)
    this.sunGlow.position.copy(SUN_DIR).multiplyScalar(350)
    this.scene.add(this.sunGlow)
  }

  buildLights() {
    const hemi = new THREE.HemisphereLight(0xa8d9e2, 0x2f5238, 1.25)
    this.scene.add(hemi)
    const sun = new THREE.DirectionalLight(0xffd9a6, 2.8)
    sun.position.copy(SUN_DIR).multiplyScalar(90)
    sun.castShadow = true
    const size = this.quality === 'low' ? 1024 : 2048
    sun.shadow.mapSize.set(size, size)
    sun.shadow.camera.left = -70
    sun.shadow.camera.right = 70
    sun.shadow.camera.top = 70
    sun.shadow.camera.bottom = -70
    sun.shadow.camera.near = 10
    sun.shadow.camera.far = 220
    sun.shadow.bias = -0.0005
    sun.shadow.normalBias = 0.035
    this.scene.add(sun)
    this.scene.add(sun.target)
    this.sunLight = sun
    const amb = new THREE.AmbientLight(0x315547, 0.55)
    this.scene.add(amb)
  }

  // ------------------------------------------------------------------ TERRAIN
  buildTerrain() {
    const size = 300
    const seg = this.quality === 'low' ? 96 : 150
    const geo = new THREE.PlaneGeometry(size, size, seg, seg)
    geo.rotateX(-Math.PI / 2)
    const pos = geo.attributes.position
    const colors = new Float32Array(pos.count * 3)
    const c = new THREE.Color()
    const sandWet = new THREE.Color(0xa48b5c)
    const sand = new THREE.Color(0xe7cd93)
    const sandLight = new THREE.Color(0xf1dcab)
    const grass = new THREE.Color(0x5b8f47)
    const grassDark = new THREE.Color(0x376b3d)
    const grassLight = new THREE.Color(0x7cae57)
    const redEarth = new THREE.Color(0x9c6542)
    const rock = new THREE.Color(0x7d7664)
    const rockDark = new THREE.Color(0x5a5a4e)
    const jungle = new THREE.Color(0x2f6543)
    const mountainTop = new THREE.Color(0x4f7354)

    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i)
      const z = pos.getZ(i)
      const h = terrainHeight(x, z)
      pos.setY(i, h)
      const r = Math.hypot(x, z)
      const n = fbm(x * 0.045 + 9, z * 0.045 - 5, 3)
      const patch = noise2(x * 0.095 - 3, z * 0.095 + 8)
      const [nx, ny, nz] = getNormal(x, z)
      const slope = 1 - ny

      if (h < 0.1) c.copy(sandWet).lerp(sand, smoothstep(-2, 0.1, h))
      else if (h < 1.55) c.copy(sand).lerp(sandLight, patch * 0.45)
      else if (h < 2.65) c.copy(sand).lerp(grass, smoothstep(1.55, 2.65, h) * (0.55 + n * 0.35))
      else {
        c.copy(grass).lerp(grassLight, patch * 0.55)
        c.lerp(grassDark, smoothstep(0.45, 0.75, n) * 0.55)
        if (r > 82) c.lerp(jungle, 0.25)
        if (h > 15) c.lerp(jungle, smoothstep(15, 24, h) * 0.3)
        if (h > 23) c.lerp(mountainTop, smoothstep(23, 29, h) * 0.5)
        if (patch > 0.66 && h < 14 && r < 95) c.lerp(redEarth, (patch - 0.66) * 0.85)
        if (slope > 0.25) c.lerp(rock, smoothstep(0.25, 0.58, slope) * 0.9)
        if (slope > 0.55) c.lerp(rockDark, smoothstep(0.55, 0.86, slope) * 0.7)
      }
      colors[i * 3] = c.r; colors[i * 3 + 1] = c.g; colors[i * 3 + 2] = c.b
    }
    geo.setAttribute('color', new THREE.BufferAttribute(colors, 3))
    geo.computeVertexNormals()

    const mat = new THREE.MeshStandardMaterial({
      vertexColors: true, roughness: 1, metalness: 0,
      map: terrainDetailTexture(),
    })
    const terrain = new THREE.Mesh(geo, mat)
    terrain.receiveShadow = true
    terrain.castShadow = false
    this.root.add(terrain)
    this.terrain = terrain

    // Shallow shelf under the water for a soft turquoise ring.
    const shelfGeo = new THREE.RingGeometry(102, 160, 80, 1)
    shelfGeo.rotateX(-Math.PI / 2)
    const shelf = new THREE.Mesh(shelfGeo, new THREE.MeshBasicMaterial({ color: 0x2a9b96, transparent: true, opacity: 0.24, depthWrite: false }))
    shelf.position.y = -0.55
    this.root.add(shelf)
  }

  buildPaths() {
    const makeRibbon = (pts, width, color, yLift) => {
      const positions = []
      const colors = []
      const indices = []
      const c = new THREE.Color(color)
      for (let i = 0; i < pts.length; i++) {
        const p = pts[i]
        const prev = pts[Math.max(0, i - 1)]
        const next = pts[Math.min(pts.length - 1, i + 1)]
        let dx = next[0] - prev[0], dz = next[2] - prev[2]
        const len = Math.hypot(dx, dz) || 1
        dx /= len; dz /= len
        const sx = -dz, sz = dx
        const w = width * (0.82 + Math.sin(i * 0.27) * 0.09 + noise2(i * 0.2, 0) * 0.12)
        const lx = p[0] + sx * w, lz = p[2] + sz * w
        const rx = p[0] - sx * w, rz = p[2] - sz * w
        positions.push(lx, terrainHeight(lx, lz) + yLift, lz, rx, terrainHeight(rx, rz) + yLift, rz)
        const shade = 0.88 + noise2(i * 0.4, 4) * 0.2
        colors.push(c.r * shade, c.g * shade, c.b * shade, c.r * shade, c.g * shade, c.b * shade)
        if (i > 0) {
          const a = (i - 1) * 2
          indices.push(a, a + 1, a + 2, a + 1, a + 3, a + 2)
        }
      }
      const g = new THREE.BufferGeometry()
      g.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3))
      g.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3))
      g.setIndex(indices)
      g.computeVertexNormals()
      return g
    }
    const mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 1, metalness: 0, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2 })
    const borderMat = new THREE.MeshStandardMaterial({ color: 0xa47b4f, roughness: 1, polygonOffset: true, polygonOffsetFactor: -1, polygonOffsetUnits: -1 })
    for (const [pts, w] of [[PATH_MAIN, 2.15], [PATH_GROVE, 1.75], [PATH_REEF, 1.8]]) {
      const p = samplePath(pts, 190)
      const border = new THREE.Mesh(makeRibbon(p, w + 0.55, 0x9a7448, 0.04), borderMat)
      border.receiveShadow = true
      this.root.add(border)
      const ribbon = new THREE.Mesh(makeRibbon(p, w, 0xd8b57e, 0.07), mat)
      ribbon.receiveShadow = true
      this.root.add(ribbon)
    }
  }

  // ------------------------------------------------------------------ OCEAN
  buildOcean() {
    const geo = new THREE.PlaneGeometry(700, 700, 150, 150)
    geo.rotateX(-Math.PI / 2)
    const mat = new THREE.ShaderMaterial({
      uniforms: {
        time: { value: 0 },
        deep: { value: new THREE.Color(0x075a72) },
        shallow: { value: new THREE.Color(0x2fc0b0) },
        crest: { value: new THREE.Color(0xc2fff0) },
        sunDir: { value: SUN_DIR.clone() },
        fogColor: { value: new THREE.Color(FOG_COLOR) },
        fogDensity: { value: 0.0031 },
      },
      vertexShader: `
        uniform float time;
        varying vec3 vWorld; varying float vWave;
        void main(){
          vec3 p = position;
          float d = length(p.xz);
          float w1 = sin(p.x * 0.19 + time * 0.9) * 0.16;
          float w2 = sin(p.z * 0.23 - time * 1.1 + p.x * 0.07) * 0.12;
          float w3 = sin((p.x + p.z) * 0.09 + time * 0.6) * 0.18;
          p.y += (w1 + w2 + w3) * smoothstep(120.0, 260.0, d) * 0.5 + (w1 + w2) * 0.35;
          vWave = w1 + w2 + w3;
          vec4 wp = modelMatrix * vec4(p, 1.0);
          vWorld = wp.xyz;
          gl_Position = projectionMatrix * viewMatrix * wp;
        }
      `,
      fragmentShader: `
        uniform float time; uniform vec3 deep; uniform vec3 shallow; uniform vec3 crest; uniform vec3 sunDir;
        uniform vec3 fogColor; uniform float fogDensity;
        varying vec3 vWorld; varying float vWave;
        void main(){
          float d = length(vWorld.xz);
          vec3 viewDir = normalize(cameraPosition - vWorld);
          float fres = pow(1.0 - max(dot(viewDir, vec3(0.,1.,0.)), 0.0), 2.2);
          float bands = sin(vWorld.x * 0.32 + time * 0.8 + sin(vWorld.z * 0.12) * 2.0) * 0.5 + 0.5;
          float bands2 = sin(vWorld.z * 0.5 - time * 1.2) * 0.5 + 0.5;
          vec3 col = mix(deep, shallow, smoothstep(30.0, 130.0, d) * 0.7 + 0.18);
          col += crest * smoothstep(0.72, 1.0, bands * bands2) * 0.22;
          col = mix(col, vec3(0.07, 0.42, 0.48), fres * 0.55);
          float spec = pow(max(dot(normalize(sunDir + viewDir), vec3(0.,1.,0.)), 0.0), 90.0);
          col += vec3(1.0, 0.86, 0.58) * spec * 0.7;
          col += crest * smoothstep(0.55, 0.9, vWave) * 0.06;
          float fog = 1.0 - exp(-fogDensity * fogDensity * distance(cameraPosition, vWorld) * distance(cameraPosition, vWorld));
          col = mix(col, fogColor, clamp(fog * 1.5, 0.0, 0.82));
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    })
    const ocean = new THREE.Mesh(geo, mat)
    ocean.position.y = 0.03
    ocean.receiveShadow = false
    ocean.frustumCulled = false
    this.root.add(ocean)
    this.ocean = ocean
    this.animated.push((dt, t) => { mat.uniforms.time.value = t })

    // Surf foam sampled around the island's shoreline.
    const foamPositions = []
    const random = mulberry32(123)
    for (let i = 0; i < 420; i++) {
      const a = random() * TAU
      let found = 0
      for (let r = 86; r < 132; r += 0.55) {
        const x = Math.cos(a) * r, z = Math.sin(a) * r
        if (terrainHeight(x, z) < 0.5 && terrainHeight(x + Math.cos(a) * 1.8, z + Math.sin(a) * 1.8) > 0.42) { found = r; break }
      }
      if (found) {
        const x = Math.cos(a) * (found + 1.6 + random() * 2.2)
        const z = Math.sin(a) * (found + 1.6 + random() * 2.2)
        foamPositions.push(x, 0.14 + random() * 0.05, z)
      }
    }
    const foamGeo = new THREE.BufferGeometry()
    foamGeo.setAttribute('position', new THREE.Float32BufferAttribute(foamPositions, 3))
    const foamMat = new THREE.PointsMaterial({
      color: 0xeafff8, size: 2.8, map: radialTexture('rgba(255,255,255,1)', 'rgba(255,255,255,0)', 64), transparent: true,
      opacity: 0.32, depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true,
    })
    this.foam = new THREE.Points(foamGeo, foamMat)
    this.root.add(this.foam)
    this.animated.push((dt, t) => { foamMat.opacity = 0.24 + Math.sin(t * 0.9) * 0.08 })
  }

  buildClouds() {
    const tex = cloudTexture()
    const random = mulberry32(82)
    for (let i = 0; i < 22; i++) {
      const mat = new THREE.SpriteMaterial({ map: tex, color: new THREE.Color(i % 4 ? 0xffe8cf : 0xffd0a2), transparent: true, opacity: 0.28 + random() * 0.2, depthWrite: false, fog: false })
      const s = new THREE.Sprite(mat)
      const a = random() * TAU
      const r = 190 + random() * 180
      s.position.set(Math.cos(a) * r, 48 + random() * 70, Math.sin(a) * r)
      const scale = 70 + random() * 110
      s.scale.set(scale, scale * 0.42, 1)
      s.userData.drift = 0.4 + random() * 0.6
      this.root.add(s)
      this.animated.push((dt, t) => { s.position.x += dt * s.userData.drift; if (s.position.x > 400) s.position.x = -400 })
    }
  }

  buildDistantLand() {
    const mat = new THREE.MeshStandardMaterial({ color: 0x2b5b4a, roughness: 1, flatShading: true })
    const specs = [
      [-230, -170, 60, 26], [210, 90, 70, 20], [40, -260, 80, 30], [-280, 140, 55, 18],
    ]
    for (const [x, z, r, h] of specs) {
      const g = new THREE.Group()
      for (let i = 0; i < 5; i++) {
        const m = new THREE.Mesh(new THREE.IcosahedronGeometry(1, 0), mat)
        m.position.set((i - 2) * r * 0.25, -2, (i % 2) * 8)
        m.scale.set(r * 0.35, h * (0.6 + (i % 3) * 0.16), r * 0.3)
        g.add(m)
      }
      g.position.set(x, 0, z)
      g.traverse(o => { o.material.fog = true })
      this.root.add(g)
    }
  }

  // ------------------------------------------------------------------ VEGETATION
  makePalmAssets() {
    const parts = []
    const trunkColor = 0x8a6a45
    let y = 0, leanX = 0, leanZ = 0
    const segCount = 6
    for (let i = 0; i < segCount; i++) {
      const segH = 1.2
      leanX += 0.09 * (i / segCount)
      leanZ += 0.03
      const geo = new THREE.CylinderGeometry(0.16 - i * 0.011, 0.23 - i * 0.012, segH, 6)
      const m = trs([leanX * i, y + segH / 2, leanZ * i], [0, 0, -0.1 * (i / segCount)], [1, 1, 1])
      parts.push({ geo, matrix: m, color: i % 2 ? trunkColor : 0x97734b })
      y += segH * 0.94
    }
    const trunkGeo = mergeParts(parts)

    const crownParts = []
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * TAU + 0.2
      const droop = 0.3 + (i % 3) * 0.16
      const cone = new THREE.ConeGeometry(0.72, 3.2, 4, 1, true)
      const m = trs([Math.cos(a) * 1.3, y + 0.1 - droop * 0.7, Math.sin(a) * 1.3], [Math.PI / 2, 0, a + Math.PI / 2], [1, 1, 0.16])
      crownParts.push({ geo: cone, matrix: m, color: i % 2 ? 0x2e6b3b : 0x3f8248 })
      const cone2 = new THREE.ConeGeometry(0.34, 1.7, 3, 1, true)
      const m2 = trs([Math.cos(a) * 2.1, y + 0.05 - droop, Math.sin(a) * 2.1], [Math.PI / 2, 0, a + Math.PI / 2], [1, 1, 0.13])
      crownParts.push({ geo: cone2, matrix: m2, color: 0x437f43 })
    }
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * TAU
      const s = new THREE.SphereGeometry(0.17, 6, 5)
      crownParts.push({ geo: s, matrix: trs([Math.cos(a) * 0.3, y - 0.35, Math.sin(a) * 0.3]), color: 0x5a3d1f })
    }
    return { trunkGeo, crownGeo: mergeParts(crownParts), height: y }
  }

  buildVegetation() {
    const rng = this.rng
    const palm = this.makePalmAssets()
    const trunkMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.95, flatShading: true })
    const crownMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.86, side: THREE.DoubleSide, flatShading: true })
    const palmSpots = []
    for (let i = 0; i < 60; i++) {
      const a = rng() * TAU, r = 58 + rng() * 57
      const x = Math.cos(a) * r, z = Math.sin(a) * r
      const h = terrainHeight(x, z)
      if (h < 1.4 || h > 9) continue
      if (this.nearStructure(x, z, 8)) continue
      if (rng() < 0.3 && Math.hypot(x - 20, z - 50) > 18) continue
      palmSpots.push({ x, z, h, s: 0.75 + rng() * 0.7, rot: rng() * TAU })
    }
    palmSpots.push({ x: 17, z: 62, h: terrainHeight(17, 62), s: 1.1, rot: 0.5 })
    palmSpots.push({ x: -2, z: 73, h: terrainHeight(-2, 73), s: 0.9, rot: 2.1 })
    palmSpots.push({ x: 39, z: 51, h: terrainHeight(39, 51), s: 0.95, rot: 4.2 })
    const trunkInst = new THREE.InstancedMesh(palm.trunkGeo, trunkMat, palmSpots.length)
    const crownInst = new THREE.InstancedMesh(palm.crownGeo, crownMat, palmSpots.length)
    trunkInst.castShadow = crownInst.castShadow = true
    trunkInst.receiveShadow = crownInst.receiveShadow = false
    const m4 = new THREE.Matrix4()
    palmSpots.forEach((p, i) => {
      m4.compose(new THREE.Vector3(p.x, p.h, p.z), new THREE.Quaternion().setFromEuler(new THREE.Euler(0, p.rot, 0)), new THREE.Vector3(p.s, p.s, p.s))
      trunkInst.setMatrixAt(i, m4); crownInst.setMatrixAt(i, m4)
      if (i % 3 === 0) this.colliders.push({ x: p.x, z: p.z, r: 0.55 * p.s })
    })
    this.root.add(trunkInst, crownInst)

    // Broadleaf / mango trees.
    const trunkParts = [{ geo: new THREE.CylinderGeometry(0.22, 0.4, 3.4, 6), matrix: trs([0, 1.7, 0]), color: 0x6e4e30 }]
    for (let i = 0; i < 3; i++) {
      const a = (i / 3) * TAU
      trunkParts.push({ geo: new THREE.CylinderGeometry(0.08, 0.18, 2.1, 5), matrix: trs([Math.cos(a) * 0.35, 3.2, Math.sin(a) * 0.35], [Math.cos(a) * 0.6, 0, Math.sin(a) * -0.6]), color: 0x65472b })
    }
    const broadTrunk = mergeParts(trunkParts)
    const canopyParts = []
    for (let i = 0; i < 7; i++) {
      const a = (i / 7) * TAU
      const r = i === 0 ? 0 : 1.55
      const s = new THREE.IcosahedronGeometry(1, 0)
      canopyParts.push({ geo: s, matrix: trs([Math.cos(a) * r, 4.2 + (i % 3) * 0.5, Math.sin(a) * r], [0, a, 0], [1.55, 1.0, 1.4]), color: i % 3 === 0 ? 0x2b6c3c : i % 3 === 1 ? 0x3b8148 : 0x21603b })
    }
    const broadCanopy = mergeParts(canopyParts)
    const broadSpots = []
    for (let i = 0; i < 95; i++) {
      const a = rng() * TAU, r = 12 + rng() * 96
      const x = Math.cos(a) * r, z = Math.sin(a) * r
      const h = terrainHeight(x, z)
      if (h < 2.4 || h > 25) continue
      if (this.nearStructure(x, z, 7) || this.nearPath(x, z, 3.5)) continue
      if (rng() < 0.4) continue
      broadSpots.push({ x, z, h, s: 0.7 + rng() * 0.85, rot: rng() * TAU })
    }
    const broadTrunkInst = new THREE.InstancedMesh(broadTrunk, trunkMat, broadSpots.length)
    const broadCanInst = new THREE.InstancedMesh(broadCanopy, new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.9, flatShading: true }), broadSpots.length)
    broadTrunkInst.castShadow = broadCanInst.castShadow = true
    broadSpots.forEach((p, i) => {
      m4.compose(new THREE.Vector3(p.x, p.h, p.z), new THREE.Quaternion().setFromEuler(new THREE.Euler(0, p.rot, 0)), new THREE.Vector3(p.s, p.s, p.s))
      broadTrunkInst.setMatrixAt(i, m4); broadCanInst.setMatrixAt(i, m4)
      if (p.s > 1.1) this.colliders.push({ x: p.x, z: p.z, r: 0.5 })
    })
    this.root.add(broadTrunkInst, broadCanInst)

    // Ferns and shrubs.
    const shrubGeo = mergeParts([
      { geo: new THREE.IcosahedronGeometry(1, 0), matrix: trs([0, 0.55, 0], [0, 0, 0], [1, 0.75, 1]), color: 0x3d7a44 },
      { geo: new THREE.IcosahedronGeometry(0.8, 0), matrix: trs([0.7, 0.4, 0.2], [0, 0.6, 0], [1, 0.7, 1]), color: 0x2f6b3d },
      { geo: new THREE.IcosahedronGeometry(0.7, 0), matrix: trs([-0.6, 0.35, -0.25], [0, -0.4, 0], [1, 0.8, 1]), color: 0x4b8a4b },
    ])
    const shrubMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.95, flatShading: true })
    const shrubSpots = []
    for (let i = 0; i < 260; i++) {
      const a = rng() * TAU, r = 10 + rng() * 105
      const x = Math.cos(a) * r, z = Math.sin(a) * r
      const h = terrainHeight(x, z)
      if (h < 2.1 || h > 26) continue
      if (this.nearStructure(x, z, 3.2) || this.nearPath(x, z, 1.8)) continue
      shrubSpots.push({ x, z, h, s: 0.55 + rng() * 0.95, rot: rng() * TAU })
    }
    const shrubInst = new THREE.InstancedMesh(shrubGeo, shrubMat, shrubSpots.length)
    shrubInst.castShadow = true; shrubInst.receiveShadow = true
    shrubSpots.forEach((p, i) => {
      m4.compose(new THREE.Vector3(p.x, p.h, p.z), new THREE.Quaternion().setFromEuler(new THREE.Euler(0, p.rot, 0)), new THREE.Vector3(p.s, p.s, p.s))
      shrubInst.setMatrixAt(i, m4)
    })
    this.root.add(shrubInst)

    // Grass tufts.
    const leafTex = leafTexture()
    const bladeGeos = []
    for (let k = 0; k < 3; k++) {
      const g = new THREE.PlaneGeometry(0.7, 0.9)
      g.applyMatrix4(trs([0, 0.42, 0], [0, (k / 3) * Math.PI, 0]))
      bladeGeos.push(g)
    }
    const tuftGeo = mergeGeometries(bladeGeos, false)
    const tuftMat = new THREE.MeshStandardMaterial({ color: 0x6fa54e, map: leafTex, alphaTest: 0.4, side: THREE.DoubleSide, roughness: 1, transparent: false })
    const tuftSpots = []
    for (let i = 0; i < 3600; i++) {
      const a = rng() * TAU, r = 8 + rng() * 108
      const x = Math.cos(a) * r, z = Math.sin(a) * r
      const h = terrainHeight(x, z)
      if (h < 2.2 || h > 27) continue
      if (this.nearStructure(x, z, 2.4) || this.nearPath(x, z, 1.2)) continue
      tuftSpots.push({ x, z, h, s: 0.6 + rng() * 1.0, rot: rng() * TAU })
    }
    const tuftInst = new THREE.InstancedMesh(tuftGeo, tuftMat, tuftSpots.length)
    tuftInst.receiveShadow = true
    const tc = new THREE.Color()
    tuftSpots.forEach((p, i) => {
      m4.compose(new THREE.Vector3(p.x, p.h, p.z), new THREE.Quaternion().setFromEuler(new THREE.Euler(0, p.rot, 0)), new THREE.Vector3(p.s, p.s, p.s))
      tuftInst.setMatrixAt(i, m4)
      tc.setHSL(0.24 + rng() * 0.06, 0.35 + rng() * 0.25, 0.32 + rng() * 0.16)
      tuftInst.setColorAt(i, tc)
    })
    this.root.add(tuftInst)

    // Flowers.
    const flowerGeo = new THREE.IcosahedronGeometry(0.11, 0)
    const flowerMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.7, emissive: 0x442200, emissiveIntensity: 0.1 })
    const flowerSpots = []
    const flowerColors = [0xff6b8a, 0xffb347, 0xf4c95d, 0xe05a9d, 0xff8c69, 0xc7a4ff]
    for (let i = 0; i < 420; i++) {
      const a = rng() * TAU, r = 12 + rng() * 102
      const x = Math.cos(a) * r, z = Math.sin(a) * r
      const h = terrainHeight(x, z)
      if (h < 2.6 || h > 16) continue
      if (this.nearStructure(x, z, 3) || this.nearPath(x, z, 1.5)) continue
      if (rng() < 0.5) continue
      flowerSpots.push({ x, z, h, s: 0.7 + rng() * 1.4, color: flowerColors[Math.floor(rng() * flowerColors.length)] })
    }
    const flowerInst = new THREE.InstancedMesh(flowerGeo, flowerMat, flowerSpots.length)
    const fc = new THREE.Color()
    flowerSpots.forEach((p, i) => {
      m4.compose(new THREE.Vector3(p.x, p.h + 0.55, p.z), new THREE.Quaternion(), new THREE.Vector3(p.s, p.s, p.s))
      flowerInst.setMatrixAt(i, m4)
      fc.setHex(p.color); flowerInst.setColorAt(i, fc)
    })
    this.root.add(flowerInst)

    // Banana plants around the village.
    for (let i = 0; i < 9; i++) {
      const a = rng() * TAU, r = 8 + rng() * 13
      const x = VILLAGE.x + Math.cos(a) * r, z = VILLAGE.z + Math.sin(a) * r
      if (this.nearStructure(x, z, 3) || this.nearPath(x, z, 1.5)) continue
      this.root.add(this.makeBananaPlant(x, terrainHeight(x, z), z, rng() * TAU))
    }
  }

  makeBananaPlant(x, y, z, rot) {
    const g = new THREE.Group()
    g.position.set(x, y, z); g.rotation.y = rot
    const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.14, 2.2, 5), colorMat(0x5c8a3e))
    stem.position.y = 1.1; stem.castShadow = true
    g.add(stem)
    for (let i = 0; i < 7; i++) {
      const a = (i / 7) * TAU
      const leaf = new THREE.Mesh(new THREE.ConeGeometry(0.42, 2.2, 4, 1, true), new THREE.MeshStandardMaterial({ color: i % 2 ? 0x4a8f43 : 0x5aa44e, roughness: 0.8, side: THREE.DoubleSide, flatShading: true }))
      leaf.position.set(Math.cos(a) * 0.9, 2.1 + (i % 2) * 0.2, Math.sin(a) * 0.9)
      leaf.rotation.set(Math.PI / 2 - 0.35, 0, a + Math.PI / 2)
      leaf.scale.set(1, 1, 0.15)
      leaf.castShadow = true
      g.add(leaf)
    }
    return g
  }

  buildRocks() {
    const geo = new THREE.DodecahedronGeometry(1, 0)
    const mat = new THREE.MeshStandardMaterial({ color: 0x7a7468, roughness: 0.98, flatShading: true })
    const spots = []
    const rng = this.rng
    for (let i = 0; i < 90; i++) {
      const a = rng() * TAU, r = 8 + rng() * 112
      const x = Math.cos(a) * r, z = Math.sin(a) * r
      const h = terrainHeight(x, z)
      if (h < 1.2 || h > 28 || this.nearStructure(x, z, 3) || this.nearPath(x, z, 1.5)) continue
      spots.push({ x, z, h, s: 0.35 + rng() * 1.4, rot: rng() * TAU })
    }
    const inst = new THREE.InstancedMesh(geo, mat, spots.length)
    inst.castShadow = true; inst.receiveShadow = true
    const m4 = new THREE.Matrix4()
    spots.forEach((p, i) => {
      m4.compose(new THREE.Vector3(p.x, p.h + p.s * 0.25, p.z), new THREE.Quaternion().setFromEuler(new THREE.Euler(p.rot * 0.2, p.rot, p.rot * 0.12)), new THREE.Vector3(p.s, p.s * 0.75, p.s * 1.1))
      inst.setMatrixAt(i, m4)
      if (p.s > 1.1) this.colliders.push({ x: p.x, z: p.z, r: p.s * 0.6 })
    })
    this.root.add(inst)

    // Shore stones.
    for (let i = 0; i < 18; i++) {
      const a = rng() * TAU, r = 100 + rng() * 18
      const x = Math.cos(a) * r, z = Math.sin(a) * r
      const h = terrainHeight(x, z)
      if (h < -0.5) continue
      const rock = new THREE.Mesh(geo, mat)
      rock.position.set(x, h + 0.2, z)
      rock.scale.set(0.5 + rng() * 1.1, 0.4 + rng() * 0.7, 0.5 + rng() * 0.8)
      rock.rotation.set(rng(), rng() * TAU, rng())
      rock.castShadow = true
      this.root.add(rock)
    }
  }

  // ------------------------------------------------------------------ VILLAGE
  buildVillage() {
    const houses = [
      { x: 17, z: 31, rot: 0.5, wall: 0xf0a35c, roof: 0x9ba4a8, trim: 0x2f6b5c },
      { x: 40, z: 30, rot: -0.6, wall: 0x7fd8c4, roof: 0x8f999c, trim: 0xc6533f },
      { x: 46, z: 43, rot: 1.9, wall: 0xffd166, roof: 0xa8b0b4, trim: 0x2f6b5c },
      { x: 16, z: 46, rot: -1.7, wall: 0xd95f4f, roof: 0x8a9497, trim: 0xf4c95d },
      { x: 34, z: 50, rot: 2.9, wall: 0x9ed0a0, roof: 0x9ba4a8, trim: 0x7a4228 },
      { x: 22, z: 22, rot: 0.85, wall: 0xe9c6a0, roof: 0x8a9497, trim: 0x2f6b5c },
    ]
    for (const h of houses) {
      const house = this.makeHouse(h)
      this.root.add(house)
      this.colliders.push({ x: h.x, z: h.z, r: 3.6 })
    }

    // Market stalls.
    const stallDefs = [
      { x: 31, z: 34, rot: -0.35, a: '#f5e6c8', b: '#d95f4f', fruit: 0xffa62b },
      { x: 35, z: 39, rot: 0.25, a: '#f5e6c8', b: '#2f9e79', fruit: 0xe05a9d },
      { x: 27, z: 39, rot: 0.9, a: '#f4c95d', b: '#2f6b5c', fruit: 0xffd166 },
    ]
    for (const s of stallDefs) { this.root.add(this.makeStall(s)); this.colliders.push({ x: s.x, z: s.z, r: 2.3 }) }

    // Colourful zinc fence behind the houses.
    for (let i = 0; i < 14; i++) {
      const a = i < 7 ? -0.2 : 2.4
      const x = 29 + Math.cos(a) * 27 + (i % 7) * 1.6
      const z = 39 + Math.sin(a) * 27
      const h = terrainHeight(x, z)
      if (h < 2) continue
      const panel = new THREE.Mesh(new THREE.BoxGeometry(1.5, 1.7, 0.06), colorMat([0x2f9e79, 0xf4c95d, 0xd95f4f, 0x4aa3c7][i % 4], { roughness: 0.8, metalness: 0.2 }))
      panel.position.set(x, h + 0.85, z)
      panel.rotation.y = a
      panel.castShadow = true
      this.root.add(panel)
    }

    // Laundry lines with swaying cloth.
    const clothColors = ['#f5e6c8', '#d95f4f', '#4aa3c7', '#f4c95d', '#2f9e79']
    for (let i = 0; i < 4; i++) {
      const x1 = 12 + i * 4, z1 = 39 + (i % 2) * 0.8
      const y1 = terrainHeight(x1, z1)
      const hanging = new THREE.Group()
      const lineGeo = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, 0, 0), new THREE.Vector3(5, 0, 0)])
      const line = new THREE.Line(lineGeo, new THREE.LineBasicMaterial({ color: 0x6b5a42 }))
      hanging.add(line)
      for (let k = 0; k < 4; k++) {
        const cloth = new THREE.Mesh(new THREE.PlaneGeometry(0.8, 0.65), new THREE.MeshStandardMaterial({ map: makeClothTexture(clothColors[(i + k) % clothColors.length]), side: THREE.DoubleSide, roughness: 1 }))
        cloth.position.set(0.8 + k * 1.05, -0.36, 0)
        cloth.castShadow = true
        hanging.add(cloth)
        const baseRot = cloth.rotation.x
        this.animated.push((dt, t) => { cloth.rotation.x = baseRot + Math.sin(t * 1.7 + k + i) * 0.16 })
      }
      hanging.position.set(x1, y1 + 2.7, z1)
      this.root.add(hanging)
    }

    // Drums, crates, planters.
    const props = [
      [30, 45, 'drum'], [33, 46, 'drum'], [29, 44.5, 'crate'], [43, 37, 'crate'], [20, 37, 'crate'], [12, 45, 'planter'], [44, 38, 'planter'],
    ]
    for (const [x, z, type] of props) {
      const h = terrainHeight(x, z)
      if (type === 'drum') {
        const g = new THREE.Group()
        g.position.set(x, h, z)
        const body = new THREE.Mesh(new THREE.CylinderGeometry(0.32, 0.4, 0.85, 10), colorMat(0x7a4228))
        body.position.y = 0.43; body.castShadow = true; g.add(body)
        const top = new THREE.Mesh(new THREE.CircleGeometry(0.31, 10), colorMat(0xe9ddc2))
        top.rotation.x = -Math.PI / 2; top.position.y = 0.861; g.add(top)
        for (let i = 0; i < 3; i++) { const band = new THREE.Mesh(new THREE.TorusGeometry(0.34, 0.02, 4, 12), colorMat(0xf4c95d)); band.rotation.x = Math.PI / 2; band.position.y = 0.2 + i * 0.25; g.add(band) }
        this.root.add(g)
      } else if (type === 'crate') {
        const c = new THREE.Mesh(new THREE.BoxGeometry(0.8, 0.6, 0.8), colorMat(0x9a6b3c))
        c.position.set(x, h + 0.3, z); c.rotation.y = hash2(x, z) * 3; c.castShadow = true; this.root.add(c)
      } else {
        const pot = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.25, 0.5, 8), colorMat(0xb5653f))
        pot.position.set(x, h + 0.25, z); pot.castShadow = true; this.root.add(pot)
        const bush = new THREE.Mesh(new THREE.IcosahedronGeometry(0.42, 0), colorMat(0x4a8f43)); bush.position.set(x, h + 0.7, z); bush.castShadow = true; this.root.add(bush)
      }
    }

    // Signposts at the village junction.
    this.root.add(this.makeSign(25.5, 46.5, 0.4, ['NINE MILE', 'MARKET ↑']))
    this.root.add(this.makeSign(44.5, 41, -0.8, ['LUMINOUS REEF', '↗ 25 MIN']))
    this.root.add(this.makeSign(12, 22, 1.9, ['SILK COTTON', 'GROVE ↖']))
    this.root.add(this.makeSign(-19, -1, 2.3, ['BLUE MOUNTAIN', 'SHRINE ↖']))
  }

  makeHouse({ x, z, rot = 0, wall = 0xf0a35c, roof = 0x9ba4a8, trim = 0x2f6b5c }) {
    const g = new THREE.Group()
    const h = terrainHeight(x, z)
    g.position.set(x, h, z)
    g.rotation.y = rot
    const wallMat = colorMat(wall, { roughness: 0.92 })
    const trimMat = colorMat(trim, { roughness: 0.7, metalness: 0.15 })
    const roofMat = new THREE.MeshStandardMaterial({ map: makeCorrugatedTexture(), color: roof, roughness: 0.52, metalness: 0.42, side: THREE.DoubleSide })
    const wood = colorMat(0x6e4b2c)

    addMesh(g, new THREE.BoxGeometry(5.2, 0.35, 4.4), colorMat(0x8b8071), [0, 0.17, 0])
    addMesh(g, new THREE.BoxGeometry(4.7, 2.75, 3.9), wallMat, [0, 1.72, 0])
    addMesh(g, new THREE.BoxGeometry(4.85, 0.12, 4.05), trimMat, [0, 3.06, 0])
    // Roof panels.
    const panelL = addMesh(g, new THREE.BoxGeometry(5.7, 0.12, 2.55), roofMat, [-1.03, 3.75, 0], [0, 0, -0.5])
    const panelR = addMesh(g, new THREE.BoxGeometry(5.7, 0.12, 2.55), roofMat, [1.03, 3.75, 0], [0, 0, 0.5])
    addMesh(g, new THREE.BoxGeometry(5.75, 0.18, 0.22), trimMat, [0, 4.3, 0])
    // Porch.
    addMesh(g, new THREE.BoxGeometry(5.1, 0.16, 1.5), wood, [0, 0.42, 2.55])
    for (const px of [-2.35, 2.35]) {
      addMesh(g, new THREE.CylinderGeometry(0.08, 0.1, 2.5, 6), wood, [px, 1.65, 3.15])
    }
    addMesh(g, new THREE.BoxGeometry(5.1, 0.08, 0.08), wood, [0, 2.18, 3.16])
    addMesh(g, new THREE.BoxGeometry(4.6, 0.08, 0.08), wood, [0, 0.92, 3.17])
    // Door and windows.
    addMesh(g, new THREE.BoxGeometry(0.92, 1.75, 0.09), colorMat(0x4b2f1d), [0, 1.45, 1.99])
    addMesh(g, new THREE.SphereGeometry(0.05, 6, 5), trimMat, [0.32, 1.4, 2.06])
    for (const wx of [-1.55, 1.55]) {
      const glow = new THREE.MeshBasicMaterial({ color: 0xffc56b, toneMapped: false })
      addMesh(g, new THREE.BoxGeometry(0.82, 0.72, 0.06), glow, [wx, 1.85, 1.985])
      addMesh(g, new THREE.BoxGeometry(0.96, 0.86, 0.04), trimMat, [wx, 1.85, 1.955])
      addMesh(g, new THREE.BoxGeometry(0.82, 0.08, 0.08), colorMat(0x4b2f1d), [wx, 1.85, 2.0])
      addMesh(g, new THREE.BoxGeometry(0.08, 0.72, 0.08), colorMat(0x4b2f1d), [wx, 1.85, 2.0])
      // Shutters.
      addMesh(g, new THREE.BoxGeometry(0.36, 0.8, 0.06), trimMat, [wx - 0.62, 1.85, 2.0], [0, 0.2, 0])
      addMesh(g, new THREE.BoxGeometry(0.36, 0.8, 0.06), trimMat, [wx + 0.62, 1.85, 2.0], [0, -0.2, 0])
    }
    // Steps.
    for (let i = 0; i < 2; i++) addMesh(g, new THREE.BoxGeometry(1.8, 0.18, 0.5), colorMat(0x8b8071), [0, 0.09 + i * 0.16, 3.0 + (1 - i) * 0.3])
    // Roof weather stains and potted plant.
    addMesh(g, new THREE.CylinderGeometry(0.22, 0.17, 0.38, 7), colorMat(0xb5653f), [2.0, 0.6, 2.85])
    addMesh(g, new THREE.IcosahedronGeometry(0.3, 0), colorMat(0x4a8f43), [2.0, 0.9, 2.85])
    return g
  }

  makeStall({ x, z, rot, a, b, fruit }) {
    const g = new THREE.Group()
    const h = terrainHeight(x, z)
    g.position.set(x, h, z); g.rotation.y = rot
    const wood = colorMat(0x7a4e2b)
    for (const sx of [-1.8, 1.8]) for (const sz of [-1.1, 1.1]) addMesh(g, new THREE.CylinderGeometry(0.06, 0.08, 2.8, 6), wood, [sx, 1.4, sz])
    addMesh(g, new THREE.BoxGeometry(4.0, 0.13, 2.5), colorMat(0x8a5a30), [0, 1.0, 0])
    addMesh(g, new THREE.BoxGeometry(3.8, 0.7, 0.16), colorMat(0x9a6b3c), [0, 0.6, -1.15])
    const canopyTex = makeStripeTexture([a, b])
    const canopy = new THREE.Mesh(new THREE.PlaneGeometry(4.4, 3.0, 1, 1), new THREE.MeshStandardMaterial({ map: canopyTex, side: THREE.DoubleSide, roughness: 0.95 }))
    canopy.rotation.x = -Math.PI / 2
    canopy.rotation.z = 0.06
    canopy.position.y = 2.75
    canopy.castShadow = true
    g.add(canopy)
    // Wavy valance.
    const valance = new THREE.Mesh(new THREE.PlaneGeometry(4.4, 0.4), new THREE.MeshStandardMaterial({ map: canopyTex, side: THREE.DoubleSide, roughness: 0.95 }))
    valance.position.set(0, 2.56, 1.5)
    g.add(valance)
    // Fruit pyramids.
    for (let i = 0; i < 3; i++) {
      for (let j = 0; j < 4 - i; j++) {
        const f = new THREE.Mesh(new THREE.SphereGeometry(0.16, 8, 6), new THREE.MeshStandardMaterial({ color: fruit, roughness: 0.55, metalness: 0.05 }))
        f.position.set(-2.4 + i * 0.35 + j * 0.28, 1.2 + i * 0.22, 0.15 + (j % 2) * 0.2)
        f.castShadow = true
        g.add(f)
      }
    }
    addMesh(g, new THREE.BoxGeometry(0.7, 0.5, 0.7), colorMat(0x9a6b3c), [1.1, 0.7, 0.2])
    addMesh(g, new THREE.BoxGeometry(0.5, 0.35, 0.5), colorMat(0x8a5a30), [1.1, 1.12, 0.2])
    // Hanging bulbs.
    for (let i = 0; i < 3; i++) {
      const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.07, 7, 5), new THREE.MeshBasicMaterial({ color: 0xffd47a, toneMapped: false }))
      bulb.position.set(-1.4 + i * 1.4, 2.45, 1.35)
      g.add(bulb)
    }
    return g
  }

  makeSign(x, z, rot, text) {
    const g = new THREE.Group()
    const h = terrainHeight(x, z)
    g.position.set(x, h, z); g.rotation.y = rot
    addMesh(g, new THREE.CylinderGeometry(0.07, 0.1, 2.5, 6), colorMat(0x6e4b2c), [0, 1.25, 0])
    const tex = makeSignTexture(text[0], text[1])
    const board = new THREE.Mesh(new THREE.BoxGeometry(1.8, 0.7, 0.08), new THREE.MeshStandardMaterial({ map: tex, roughness: 0.9 }))
    board.position.set(0, 2.15, 0.08)
    board.castShadow = true
    g.add(board)
    const edge = new THREE.Mesh(new THREE.BoxGeometry(1.92, 0.82, 0.04), colorMat(0x5b3b20))
    edge.position.set(0, 2.15, 0.02); g.add(edge)
    return g
  }

  // ------------------------------------------------------------------ BEACH
  buildBeachProps() {
    this.root.add(this.makeBoat(4, 83, 1.1))
    this.root.add(this.makeBoat(-15, 96, 2.3, 0.78))
    // Picnic / fishing spot.
    const h = terrainHeight(13, 76)
    const post = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.1, 3.4, 6), colorMat(0x6e4b2c))
    post.position.set(13, h + 1.7, 76); post.castShadow = true; this.root.add(post)
    const flagTex = makeClothTexture('#2f9e79')
    const flag = new THREE.Mesh(new THREE.PlaneGeometry(1.3, 0.8), new THREE.MeshStandardMaterial({ map: flagTex, side: THREE.DoubleSide, roughness: 1 }))
    flag.position.set(13.7, h + 3.0, 76); this.root.add(flag)
    this.animated.push((dt, t) => { flag.rotation.y = Math.sin(t * 2.2) * 0.2 })
    // Starfish and shells.
    for (let i = 0; i < 14; i++) {
      const a = this.rng() * TAU, r = 100 + this.rng() * 12
      const x = Math.cos(a) * r, z = Math.sin(a) * r
      const y = terrainHeight(x, z)
      if (y < 0.4 || y > 1.4) continue
      const star = new THREE.Mesh(new THREE.CircleGeometry(0.18, 5), colorMat(0xff8c69))
      star.rotation.x = -Math.PI / 2; star.position.set(x, y + 0.03, z); this.root.add(star)
    }
  }

  makeBoat(x, z, rot, scale = 1) {
    const g = new THREE.Group()
    const h = terrainHeight(x, z)
    g.position.set(x, h + 0.2, z); g.rotation.y = rot; g.scale.setScalar(scale)
    const hull = new THREE.Mesh(new THREE.CapsuleGeometry(0.75, 3.0, 4, 10), new THREE.MeshStandardMaterial({ color: 0x8a5a30, roughness: 0.8, flatShading: true }))
    hull.rotation.x = Math.PI / 2; hull.rotation.z = Math.PI / 2; hull.scale.y = 0.55; hull.position.y = 0.4
    hull.castShadow = true; g.add(hull)
    const inner = new THREE.Mesh(new THREE.BoxGeometry(1.0, 0.45, 3.2), colorMat(0x3b2a1b))
    inner.position.y = 0.5; g.add(inner)
    const mast = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.07, 3.4, 5), colorMat(0x6e4b2c))
    mast.position.set(0, 2.1, -0.2); mast.castShadow = true; g.add(mast)
    const sail = new THREE.Mesh(new THREE.PlaneGeometry(2.0, 2.4, 3, 3), new THREE.MeshStandardMaterial({ color: 0xf2e6c9, side: THREE.DoubleSide, roughness: 0.9 }))
    sail.position.set(0, 2.4, 0.75); sail.rotation.y = Math.PI / 2; sail.rotation.z = 0.1; sail.castShadow = true; g.add(sail)
    // Oars.
    for (const s of [-1, 1]) {
      const oar = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.04, 2.2, 5), colorMat(0x9a6b3c))
      oar.position.set(s * 0.9, 0.8, 0.8); oar.rotation.z = s * 0.5; g.add(oar)
    }
    const baseY = h + 0.2
    this.animated.push((dt, t) => { g.position.y = baseY + Math.sin(t * 1.1 + x) * 0.08; g.rotation.z = Math.sin(t * 0.9 + z) * 0.02 })
    return g
  }

  // ------------------------------------------------------------------ WATERFALL
  buildWaterfall() {
    const g = new THREE.Group()
    g.position.set(WATERFALL.x, 0, WATERFALL.z)
    const rockMat = new THREE.MeshStandardMaterial({ color: 0x5c5f50, roughness: 0.98, flatShading: true })
    for (let i = 0; i < 12; i++) {
      const a = (i / 12) * TAU
      const r = 7 + (i % 3) * 1.2
      const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(1, 0), rockMat)
      rock.position.set(Math.cos(a) * r, terrainHeight(WATERFALL.x + Math.cos(a) * r, WATERFALL.z + Math.sin(a) * r) + 0.3, Math.sin(a) * r)
      rock.scale.set(1.4 + (i % 3) * 0.6, 1.6 + (i % 4) * 0.7, 1.2 + (i % 2) * 0.5)
      rock.rotation.set(i, i * 2, i * 1.3)
      rock.castShadow = true; rock.receiveShadow = true
      g.add(rock)
      this.colliders.push({ x: WATERFALL.x + Math.cos(a) * r, z: WATERFALL.z + Math.sin(a) * r, r: 1.6 })
    }
    // Upper ledge.
    for (let i = 0; i < 5; i++) {
      const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(1, 0), rockMat)
      rock.position.set(-4 + i * 2.0, 14.4 + (i % 2) * 0.7, -3.2)
      rock.scale.set(1.8, 1.2, 2.0)
      rock.castShadow = true
      g.add(rock)
    }
    // Waterfall sheet.
    const fallMat = new THREE.ShaderMaterial({
      transparent: true, side: THREE.DoubleSide, depthWrite: false,
      uniforms: { time: { value: 0 } },
      vertexShader: `varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
      fragmentShader: `
        uniform float time; varying vec2 vUv;
        void main(){
          float stripes = sin(vUv.x * 46.0 + sin(vUv.y * 12.0 + time * 3.0) * 2.0) * 0.5 + 0.5;
          float streaks = sin(vUv.y * 30.0 - time * 7.0 + vUv.x * 8.0) * 0.5 + 0.5;
          float a = (0.34 + stripes * 0.24 + streaks * 0.12) * smoothstep(0.0, 0.12, vUv.y) * smoothstep(1.0, 0.92, vUv.y);
          vec3 col = mix(vec3(0.55, 0.86, 0.9), vec3(1.0), stripes * 0.7);
          gl_FragColor = vec4(col, a);
        }
      `,
    })
    const fall = new THREE.Mesh(new THREE.PlaneGeometry(3.3, 8.2, 1, 1), fallMat)
    fall.position.set(2.1, 10.6, -3.1)
    fall.rotation.x = 0.04
    g.add(fall)
    this.waterfalls.push(fallMat)
    // Pool.
    const pool = new THREE.Mesh(new THREE.CircleGeometry(6.5, 32), new THREE.MeshStandardMaterial({ color: 0x3ec9c0, roughness: 0.1, metalness: 0.2, transparent: true, opacity: 0.72, emissive: 0x0d6b72, emissiveIntensity: 0.4 }))
    pool.rotation.x = -Math.PI / 2
    pool.position.y = terrainHeight(WATERFALL.x, WATERFALL.z) + 0.1
    g.add(pool)
    const ring = new THREE.Mesh(new THREE.RingGeometry(6.2, 6.6, 32), new THREE.MeshBasicMaterial({ color: 0x9ffff1, transparent: true, opacity: 0.32, side: THREE.DoubleSide, depthWrite: false }))
    ring.rotation.x = -Math.PI / 2; ring.position.y = pool.position.y + 0.02; g.add(ring)
    this.animated.push((dt, t) => { fallMat.uniforms.time.value = t; ring.scale.setScalar(1 + Math.sin(t * 1.4) * 0.02) })
    // Mist points.
    const mistCount = 70
    const arr = new Float32Array(mistCount * 3)
    for (let i = 0; i < mistCount; i++) { arr[i * 3] = 2 + (Math.random() - 0.5) * 5; arr[i * 3 + 1] = 6.7 + Math.random() * 4; arr[i * 3 + 2] = -3 + (Math.random() - 0.5) * 4 }
    const mistGeo = new THREE.BufferGeometry(); mistGeo.setAttribute('position', new THREE.BufferAttribute(arr, 3))
    const mist = new THREE.Points(mistGeo, new THREE.PointsMaterial({ color: 0xd9fff9, size: 1.5, map: radialTexture('rgba(255,255,255,1)', 'rgba(255,255,255,0)', 64), transparent: true, opacity: 0.32, depthWrite: false, blending: THREE.AdditiveBlending }))
    g.add(mist)
    this.animated.push((dt, t) => { mist.rotation.y = t * 0.06 })
    this.root.add(g)
    this.colliders.push({ x: WATERFALL.x + 2, z: WATERFALL.z - 2, r: 4.5 })
  }

  // ------------------------------------------------------------------ SHRINES
  buildShrines() {
    this.shrines.mountain = this.makeShrine('mountain', SHRINE_NIAN, '#f4c95d')
    this.shrines.reef = this.makeShrine('reef', SHRINE_BAKUNAWA, '#9f7bff')
    this.shrines.canopy = this.makeShrine('canopy', SHRINE_QUETZAL, '#8ff0ce')
  }

  makeShrine(kind, spec, colorHex) {
    const g = new THREE.Group()
    g.position.set(spec.x, spec.y, spec.z)
    const stone = new THREE.MeshStandardMaterial({ color: kind === 'reef' ? 0x6b6f68 : 0x777266, roughness: 0.95, flatShading: true })
    const darkStone = new THREE.MeshStandardMaterial({ color: 0x4a4b43, roughness: 0.98, flatShading: true })
    const color = new THREE.Color(colorHex)
    const runeMat = new THREE.MeshBasicMaterial({ color, toneMapped: false })
    const glowMat = new THREE.MeshStandardMaterial({ color, emissive: colorHex, emissiveIntensity: 2.2, roughness: 0.2 })
    // Dais.
    addMesh(g, new THREE.CylinderGeometry(4.2, 4.8, 0.42, 12), stone, [0, 0.2, 0])
    addMesh(g, new THREE.CylinderGeometry(3.35, 3.5, 0.16, 12), darkStone, [0, 0.48, 0])
    const runeRing = new THREE.Mesh(new THREE.TorusGeometry(3.55, 0.045, 4, 64), runeMat)
    runeRing.rotation.x = -Math.PI / 2; runeRing.position.y = 0.5; g.add(runeRing)
    const innerRing = new THREE.Mesh(new THREE.TorusGeometry(2.1, 0.03, 4, 48), new THREE.MeshBasicMaterial({ color, toneMapped: false, transparent: true, opacity: 0.5 }))
    innerRing.rotation.x = -Math.PI / 2; innerRing.position.y = 0.51; g.add(innerRing)
    // Standing stones.
    const stones = []
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * TAU + 0.2
      const r = 7.2
      const hgt = 2.1 + (i % 3) * 0.7
      const monolith = addMesh(g, new THREE.DodecahedronGeometry(1, 0), i % 2 ? stone : darkStone, [Math.cos(a) * r, hgt * 0.58, Math.sin(a) * r], [0, -a, 0], [0.55, hgt * 0.75, 0.5])
      const rune = addMesh(g, new THREE.BoxGeometry(0.12, 0.4, 0.03), runeMat, [Math.cos(a) * (r - 0.4), hgt * 0.7, Math.sin(a) * (r - 0.4)], [0, -a, 0])
      stones.push({ monolith, rune, phase: i })
    }
    // Kind-specific centrepiece.
    const crystals = []
    if (kind === 'mountain') {
      // Arch of stacked stones.
      for (let i = 0; i < 7; i++) {
        const a = -0.8 + i * 0.27
        addMesh(g, new THREE.BoxGeometry(0.7, 1.4, 0.6), i % 2 ? stone : darkStone, [Math.cos(a) * 4.4, 2.2 + Math.sin(a) * 0.6, Math.sin(a) * 4.4], [0, -a, 0.2])
      }
      const crystal = addMesh(g, new THREE.OctahedronGeometry(0.7, 0), glowMat, [0, 2.2, 0])
      crystals.push(crystal)
    } else if (kind === 'reef') {
      // Driftwood arch and coral fan.
      for (const s of [-1, 1]) {
        const arch = new THREE.Mesh(new THREE.TorusGeometry(3.0, 0.18, 5, 12, Math.PI), new THREE.MeshStandardMaterial({ color: 0x5b4a3a, roughness: 0.95 }))
        arch.position.set(0, 1.2, 0); arch.rotation.z = s > 0 ? 0 : Math.PI; arch.rotation.y = Math.PI / 2; g.add(arch)
      }
      for (let i = 0; i < 7; i++) {
        const coral = addMesh(g, new THREE.ConeGeometry(0.18, 0.9 + (i % 4) * 0.35, 5), new THREE.MeshStandardMaterial({ color: i % 2 ? 0xff6b8a : 0xc7a4ff, roughness: 0.7, emissive: i % 2 ? 0x6a1e32 : 0x2f1f5e, emissiveIntensity: 0.3 }), [Math.cos(i) * 2.2, 0.8, Math.sin(i) * 2.2], [0.2, i, 0.2])
      }
      const crystal = addMesh(g, new THREE.OctahedronGeometry(0.65, 0), glowMat, [0, 2.1, 0])
      crystals.push(crystal)
    } else {
      // Roots and hanging lanterns.
      for (let i = 0; i < 4; i++) {
        const a = (i / 4) * TAU
        addMesh(g, new THREE.CylinderGeometry(0.18, 0.35, 4.2, 6), new THREE.MeshStandardMaterial({ color: 0x4a3524, roughness: 1 }), [Math.cos(a) * 2.8, 2.2, Math.sin(a) * 2.8], [Math.sin(a) * 0.4, 0, -Math.cos(a) * 0.4])
      }
      for (let i = 0; i < 5; i++) {
        const a = (i / 5) * TAU
        const lantern = addMesh(g, new THREE.SphereGeometry(0.18, 8, 6), glowMat, [Math.cos(a) * 3.1, 3.0 + (i % 2) * 0.5, Math.sin(a) * 3.1])
        crystals.push(lantern)
      }
    }
    // Floating shards.
    for (let i = 0; i < 4; i++) {
      const a = (i / 4) * TAU
      const shard = addMesh(g, new THREE.OctahedronGeometry(0.16, 0), glowMat, [Math.cos(a) * 3.9, 1.2, Math.sin(a) * 3.9])
      crystals.push(shard)
    }
    const aura = glowSprite(colorHex, 14, 0.16)
    aura.position.y = 1.6
    g.add(aura)
    const beam = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.45, 60, 8, 1, true), new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.08, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide }))
    beam.position.y = 30
    g.add(beam)
    // Brazier fires.
    const braziers = []
    for (let i = 0; i < 2; i++) {
      const a = i * Math.PI + 0.4
      const brazier = new THREE.Mesh(new THREE.CylinderGeometry(0.32, 0.24, 0.55, 7), darkStone)
      brazier.position.set(Math.cos(a) * 5.2, 0.7, Math.sin(a) * 5.2); g.add(brazier)
      const flame = glowSprite(0xffa347, 1.4, 0.8)
      flame.position.set(brazier.position.x, 1.3, brazier.position.z); g.add(flame)
      braziers.push(flame)
    }
    this.colliders.push({ x: spec.x, z: spec.z, r: 3.0 })
    this.animated.push((dt, t) => {
      crystals.forEach((c, i) => {
        c.rotation.y = t * (0.5 + i * 0.1)
        c.position.y += Math.sin(t * 1.2 + i) * 0.002
      })
      aura.material.opacity = 0.12 + Math.sin(t * 2) * 0.04
      beam.material.opacity = 0.055 + Math.sin(t * 1.4) * 0.02
      braziers.forEach((f, i) => { f.scale.setScalar(1.15 + Math.sin(t * 9 + i) * 0.2) })
      runeRing.material.opacity = 1
    })
    this.root.add(g)
    return { group: g, crystals, beam, color: colorHex, colorObj: color, aura, runeRing }
  }

  // ------------------------------------------------------------------ GREAT TREE
  buildSilkTree() {
    const g = new THREE.Group()
    g.position.set(SILK_TREE.x, SILK_TREE.y, SILK_TREE.z)
    const bark = new THREE.MeshStandardMaterial({ color: 0x5f4a33, roughness: 1, flatShading: true })
    const barkDark = new THREE.MeshStandardMaterial({ color: 0x453525, roughness: 1, flatShading: true })
    const leaf = new THREE.MeshStandardMaterial({ color: 0x2c7045, roughness: 0.92, flatShading: true })
    const leafDark = new THREE.MeshStandardMaterial({ color: 0x1c5837, roughness: 0.92, flatShading: true })
    const leafLight = new THREE.MeshStandardMaterial({ color: 0x3f8a50, roughness: 0.92, flatShading: true })
    // Buttress roots.
    for (let i = 0; i < 9; i++) {
      const a = (i / 9) * TAU
      const root = new THREE.Mesh(new THREE.CylinderGeometry(0.5, 1.4, 9, 6), i % 2 ? bark : barkDark)
      root.position.set(Math.cos(a) * 4.8, 2.6, Math.sin(a) * 4.8)
      root.rotation.set(Math.sin(a) * 0.65, 0, -Math.cos(a) * 0.65)
      root.castShadow = true; root.receiveShadow = true
      g.add(root)
    }
    // Trunk.
    addMesh(g, new THREE.CylinderGeometry(3.4, 5.3, 22, 12), bark, [0, 11, 0])
    addMesh(g, new THREE.CylinderGeometry(2.1, 3.5, 8, 10), barkDark, [0, 25, 0])
    // Canopy clusters.
    const clusters = []
    for (let i = 0; i < 15; i++) {
      const a = (i / 15) * TAU
      const r = i === 0 ? 0 : 7 + (i % 4) * 2.4
      const y = 29 + (i % 5) * 1.8 + (i === 0 ? 2 : 0)
      const m = new THREE.Mesh(new THREE.IcosahedronGeometry(1, 1), i % 3 === 0 ? leafDark : i % 3 === 1 ? leaf : leafLight)
      m.position.set(Math.cos(a) * r, y, Math.sin(a) * r)
      m.scale.set(5.4 + (i % 3) * 1.1, 2.7 + (i % 2) * 0.8, 5.0 + (i % 4) * 1.0)
      m.castShadow = true
      g.add(m)
      clusters.push(m)
    }
    // Vines and lanterns.
    const lanterns = []
    for (let i = 0; i < 11; i++) {
      const a = (i / 11) * TAU
      const r = 5.5 + (i % 4) * 2.2
      const topY = 27 - (i % 3) * 2
      const len = 4 + (i % 5) * 1.8
      const vine = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.06, len, 4), new THREE.MeshStandardMaterial({ color: 0x3c5c36, roughness: 1 }))
      vine.position.set(Math.cos(a) * r, topY - len / 2, Math.sin(a) * r)
      g.add(vine)
      const l = new THREE.Mesh(new THREE.SphereGeometry(0.25, 8, 6), new THREE.MeshStandardMaterial({ color: 0xffd166, emissive: 0xffa733, emissiveIntensity: 2.4, roughness: 0.2 }))
      l.position.set(Math.cos(a) * r, topY - len, Math.sin(a) * r)
      g.add(l)
      lanterns.push(l)
    }
    // Ritual circle.
    const runeMat = new THREE.MeshBasicMaterial({ color: 0xf4c95d, toneMapped: false })
    for (let i = 0; i < 3; i++) {
      const ring = new THREE.Mesh(new THREE.TorusGeometry(8 - i * 1.4, 0.04, 4, 64), new THREE.MeshBasicMaterial({ color: i === 1 ? 0x8ff0ce : 0xf4c95d, transparent: true, opacity: 0.55 - i * 0.1, toneMapped: false }))
      ring.rotation.x = -Math.PI / 2; ring.position.y = 0.12 + i * 0.01; g.add(ring)
    }
    for (let i = 0; i < 16; i++) {
      const a = (i / 16) * TAU
      const rune = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.04, 0.14), runeMat)
      rune.position.set(Math.cos(a) * 7.6, 0.14, Math.sin(a) * 7.6); rune.rotation.y = -a; g.add(rune)
    }
    const aura = glowSprite(0xf4c95d, 30, 0.17)
    aura.position.y = 4
    g.add(aura)
    this.colliders.push({ x: SILK_TREE.x, z: SILK_TREE.z, r: 6.4 })
    this.animated.push((dt, t) => {
      clusters.forEach((c, i) => { c.position.y += Math.sin(t * 0.45 + i) * 0.0015 })
      lanterns.forEach((l, i) => { l.scale.setScalar(1 + Math.sin(t * 2.5 + i) * 0.08) })
      aura.material.opacity = 0.13 + Math.sin(t * 1.1) * 0.04
    })
    this.root.add(g)
    this.silkTree = g
  }

  // ------------------------------------------------------------------ NPCS
  buildNPCs() {
    for (const npc of NPCS) {
      const g = new THREE.Group()
      const h = terrainHeight(npc.x, npc.z)
      g.position.set(npc.x, h, npc.z)
      g.rotation.y = npc.id === 'nya' ? 2.7 : -0.5
      const skin = new THREE.MeshStandardMaterial({ color: npc.id === 'nya' ? 0x6e432b : 0x5a3724, roughness: 0.8, flatShading: true })
      const dress = new THREE.MeshStandardMaterial({ color: npc.id === 'nya' ? 0x2f6b5c : 0x4a8aa8, roughness: 0.85, flatShading: true })
      const accent = npc.id === 'nya' ? 0xf4c95d : 0xd95f4f
      addMesh(g, new THREE.CylinderGeometry(0.42, 0.65, 1.5, 7), dress, [0, 1.0, 0])
      addMesh(g, new THREE.SphereGeometry(0.28, 10, 8), dress, [0, 1.8, 0], [0, 0, 0], [1.1, 1.2, 0.9])
      addMesh(g, new THREE.CylinderGeometry(0.13, 0.15, 0.22, 7), skin, [0, 2.03, 0])
      addMesh(g, new THREE.SphereGeometry(0.23, 10, 8), skin, [0, 2.22, 0])
      addMesh(g, new THREE.SphereGeometry(0.23, 8, 6), new THREE.MeshStandardMaterial({ color: npc.id === 'nya' ? 0x2a1b12 : 0x171310, roughness: 1 }), [0, 2.32, 0.03], [0, 0, 0], [1.05, 0.7, 1.05])
      if (npc.id === 'nya') {
        // Headwrap and beads.
        addMesh(g, new THREE.TorusGeometry(0.25, 0.09, 5, 14), new THREE.MeshStandardMaterial({ color: 0xd95f4f, roughness: 0.85 }), [0, 2.38, 0], [Math.PI / 2, 0, 0])
        addMesh(g, new THREE.ConeGeometry(0.2, 0.45, 6), new THREE.MeshStandardMaterial({ color: 0xd95f4f, roughness: 0.85 }), [0.2, 2.45, 0.02], [0, 0, -0.5])
        for (let i = 0; i < 3; i++) addMesh(g, new THREE.TorusGeometry(0.32 + i * 0.03, 0.025, 4, 12), new THREE.MeshStandardMaterial({ color: accent, metalness: 0.4, roughness: 0.4 }), [0, 1.85 - i * 0.12, 0], [Math.PI / 2, 0, 0])
      } else {
        // Cap and shirt.
        addMesh(g, new THREE.CylinderGeometry(0.24, 0.26, 0.12, 8), new THREE.MeshStandardMaterial({ color: 0x2f4b5e, roughness: 0.9 }), [0, 2.42, 0])
        addMesh(g, new THREE.BoxGeometry(0.55, 0.55, 0.12), new THREE.MeshStandardMaterial({ color: 0xe9ddc2, roughness: 0.9 }), [0, 1.9, -0.28])
        addMesh(g, new THREE.BoxGeometry(0.6, 0.4, 0.4), new THREE.MeshStandardMaterial({ color: 0x4a8aa8, roughness: 0.9 }), [0, 1.1, 0.05])
      }
      // Arms.
      for (const s of [-1, 1]) addMesh(g, new THREE.CylinderGeometry(0.07, 0.06, 0.75, 5), skin, [s * 0.43, 1.4, 0], [0, 0, s * 0.14])
      // Floating marker.
      const marker = new THREE.Mesh(new THREE.OctahedronGeometry(0.18, 0), new THREE.MeshBasicMaterial({ color: 0xf4c95d, toneMapped: false }))
      marker.position.y = 3.05; g.add(marker)
      const halo = glowSprite(0xf4c95d, 1.1, 0.45); halo.position.y = 3.05; g.add(halo)
      this.animated.push((dt, t) => {
        marker.rotation.y = t * 1.6
        marker.position.y = 3.05 + Math.sin(t * 1.6) * 0.12
        halo.position.y = marker.position.y
      })
      this.root.add(g)
      const npcData = { ...npc, group: g, marker, halo }
      this.npcModels.push(npcData)
      this.colliders.push({ x: npc.x, z: npc.z, r: 0.9 })
    }
  }

  // ------------------------------------------------------------------ PICKUPS
  buildPickups() {
    const spots = [
      { type: 'mango', x: 20, z: 52 }, { type: 'mango', x: -18, z: 4 }, { type: 'mango', x: 54, z: 33 },
      { type: 'mango', x: 3, z: -30 }, { type: 'mango', x: -38, z: -4 }, { type: 'mango', x: 36, z: 21 },
      { type: 'bloom', x: 7, z: 68 }, { type: 'bloom', x: -24, z: -13 }, { type: 'bloom', x: 58, z: 17 }, { type: 'bloom', x: 12, z: -44 },
      { type: 'orbs', x: 30, z: 42 }, { type: 'orbs', x: -40, z: -22 }, { type: 'orbs', x: 62, z: 12 },
    ]
    for (const s of spots) {
      const h = terrainHeight(s.x, s.z)
      const g = new THREE.Group()
      g.position.set(s.x, h, s.z)
      const coreMat = s.type === 'mango'
        ? new THREE.MeshStandardMaterial({ color: 0xff8c3a, emissive: 0x6d2a05, emissiveIntensity: 0.45, roughness: 0.55 })
        : s.type === 'bloom'
          ? new THREE.MeshStandardMaterial({ color: 0x79dcff, emissive: 0x1e8fb6, emissiveIntensity: 1.4, roughness: 0.2 })
          : new THREE.MeshStandardMaterial({ color: 0x37d6a5, emissive: 0x1e8f70, emissiveIntensity: 1.4, roughness: 0.2 })
      let core
      if (s.type === 'mango') {
        core = new THREE.Mesh(new THREE.SphereGeometry(0.24, 10, 8), coreMat)
        core.scale.set(0.85, 1.15, 0.85); core.position.y = 0.55
        const leafM = new THREE.Mesh(new THREE.ConeGeometry(0.14, 0.32, 4), colorMat(0x4a8f43)); leafM.position.set(0.12, 0.78, 0); leafM.rotation.z = -0.6; g.add(leafM)
      } else if (s.type === 'bloom') {
        core = new THREE.Mesh(new THREE.OctahedronGeometry(0.25, 0), coreMat); core.position.y = 0.6
        for (let i = 0; i < 5; i++) {
          const a = (i / 5) * TAU
          const petal = new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.4, 4), new THREE.MeshStandardMaterial({ color: 0xc7a4ff, emissive: 0x4a2b8f, emissiveIntensity: 0.5, roughness: 0.5 }))
          petal.position.set(Math.cos(a) * 0.22, 0.6, Math.sin(a) * 0.22); petal.rotation.set(Math.PI / 2, 0, a); g.add(petal)
        }
      } else {
        core = new THREE.Mesh(new THREE.SphereGeometry(0.22, 12, 9), coreMat); core.position.y = 0.5
        const ring = new THREE.Mesh(new THREE.TorusGeometry(0.34, 0.03, 4, 16), new THREE.MeshBasicMaterial({ color: 0x8ff0ce, toneMapped: false }))
        ring.rotation.x = Math.PI / 2; ring.position.y = 0.5; g.add(ring)
      }
      core.castShadow = true
      g.add(core)
      const halo = glowSprite(s.type === 'mango' ? 0xffa347 : s.type === 'bloom' ? 0x79dcff : 0x37d6a5, 1.7, 0.4)
      halo.position.y = 0.6; g.add(halo)
      g.userData.baseY = h
      this.animated.push((dt, t) => { core.rotation.y = t * 1.2; core.position.y = 0.55 + Math.sin(t * 2 + s.x) * 0.1; halo.position.y = core.position.y })
      this.root.add(g)
      this.pickups.push({ ...s, group: g, active: true, y: h })
    }
  }

  // ------------------------------------------------------------------ PARTICLES
  buildParticles() {
    // Pollen motes all across the island.
    const count = this.quality === 'low' ? 220 : 520
    const pos = new Float32Array(count * 3)
    const phase = new Float32Array(count)
    const rng = this.rng
    for (let i = 0; i < count; i++) {
      const a = rng() * TAU, r = 10 + rng() * 110
      const x = Math.cos(a) * r, z = Math.sin(a) * r
      pos[i * 3] = x; pos[i * 3 + 1] = terrainHeight(x, z) + 0.8 + rng() * 8; pos[i * 3 + 2] = z
      phase[i] = rng() * TAU
    }
    const geo = new THREE.BufferGeometry(); geo.setAttribute('position', new THREE.BufferAttribute(pos, 3))
    const mat = new THREE.PointsMaterial({ color: 0xfff0bf, size: 0.13, map: radialTexture('rgba(255,255,255,1)', 'rgba(255,255,255,0)', 32), transparent: true, opacity: 0.55, depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true })
    const points = new THREE.Points(geo, mat)
    this.root.add(points)
    this.animated.push((dt, t) => {
      const arr = geo.attributes.position.array
      for (let i = 0; i < count; i++) {
        arr[i * 3 + 1] += Math.sin(t * 0.7 + phase[i]) * dt * 0.18
        arr[i * 3] += Math.cos(t * 0.4 + phase[i]) * dt * 0.09
      }
      geo.attributes.position.needsUpdate = true
    })

    // Fireflies near the grove.
    const fireCount = this.quality === 'low' ? 60 : 150
    const fpos = new Float32Array(fireCount * 3)
    const fphase = new Float32Array(fireCount)
    for (let i = 0; i < fireCount; i++) {
      const a = rng() * TAU, r = rng() * 33
      const x = 2 + Math.cos(a) * r, z = -46 + Math.sin(a) * r
      fpos[i * 3] = x; fpos[i * 3 + 1] = terrainHeight(x, z) + 0.8 + rng() * 4.5; fpos[i * 3 + 2] = z; fphase[i] = rng() * TAU
    }
    const fgeo = new THREE.BufferGeometry(); fgeo.setAttribute('position', new THREE.BufferAttribute(fpos, 3))
    const fmat = new THREE.PointsMaterial({ color: 0xbfffa1, size: 0.28, map: radialTexture('rgba(255,255,255,1)', 'rgba(255,255,255,0)', 32), transparent: true, opacity: 0.85, depthWrite: false, blending: THREE.AdditiveBlending })
    const fireflies = new THREE.Points(fgeo, fmat)
    this.root.add(fireflies)
    this.animated.push((dt, t) => {
      const arr = fgeo.attributes.position.array
      for (let i = 0; i < fireCount; i++) {
        arr[i * 3 + 1] += Math.sin(t * 1.6 + fphase[i]) * dt * 0.28
        arr[i * 3] += Math.cos(t * 1.1 + fphase[i]) * dt * 0.12
      }
      fgeo.attributes.position.needsUpdate = true
      fmat.opacity = 0.6 + Math.sin(t * 2.2) * 0.18
    })
  }

  // ------------------------------------------------------------------ WAYPOINTS
  buildWaypoints() {
    const defs = [
      ['nya', NPCS[0].x, NPCS[0].z, 0xf4c95d],
      ['mountain', SHRINES.mountain.x, SHRINES.mountain.z, 0xf4c95d],
      ['reef', SHRINES.reef.x, SHRINES.reef.z, 0xc7a4ff],
      ['canopy', SHRINES.canopy.x, SHRINES.canopy.z, 0x8ff0ce],
      ['tree', SHRINES.tree.x, SHRINES.tree.z, 0xf4c95d],
      ['fitz', NPCS[1].x, NPCS[1].z, 0x37d6a5],
    ]
    for (const [id, x, z, color] of defs) {
      const y = terrainHeight(x, z)
      const w = buildWaypoint(color)
      w.position.set(x, y, z)
      w.visible = false
      this.root.add(w)
      this.waypoints[id] = w
    }
  }

  showWaypoint(id, visible = true) {
    for (const key in this.waypoints) this.waypoints[key].visible = false
    if (id && this.waypoints[id]) this.waypoints[id].visible = visible
  }

  // ------------------------------------------------------------------ HELPERS
  nearPath(x, z, pad = 0) {
    for (const p of this.pathSample) {
      if (Math.abs(p[0] - x) < 8 + pad && Math.abs(p[2] - z) < 8 + pad) {
        if (Math.hypot(p[0] - x, p[2] - z) < 2.2 + pad) return true
      }
    }
    return false
  }

  nearStructure(x, z, pad = 0) {
    const spots = [
      [VILLAGE.x, VILLAGE.z, 14], [WATERFALL.x, WATERFALL.z, 7], [SILK_TREE.x, SILK_TREE.z, 9],
      [SHRINE_NIAN.x, SHRINE_NIAN.z, 10], [SHRINE_BAKUNAWA.x, SHRINE_BAKUNAWA.z, 9], [SHRINE_QUETZAL.x, SHRINE_QUETZAL.z, 9],
    ]
    for (const [sx, sz, r] of spots) if (Math.hypot(x - sx, z - sz) < r + pad) return true
    return false
  }

  isBlocked(x, z, radius = 0.4) {
    for (const c of this.colliders) {
      if (Math.hypot(x - c.x, z - c.z) < c.r + radius) return true
    }
    return false
  }

  update(dt, t) {
    this.time = t
    if (this.sky) this.sky.material.uniforms.time.value = t
    for (const fn of this.animated) fn(dt, t)
    if (this.sunLight) {
      const target = new THREE.Vector3(0, 0, 0)
      this.sunLight.target.position.copy(target)
    }
  }
}

// A tiny procedural soundscape: no external audio assets.
const NOTE = (midi) => 440 * Math.pow(2, (midi - 69) / 12)

export class SoundEngine {
  constructor() {
    this.ctx = null
    this.master = null
    this.musicGain = null
    this.sfxGain = null
    this.ambientGain = null
    this.enabled = localStorage.getItem('soulyard-muted') !== '1'
    this.started = false
    this.nextStep = 0
    this.step = 0
    this.bpm = 84
    this.musicTimer = null
    this.birdTimer = null
    this.ambienceStarted = false
    this._lastShot = 0
  }

  ensure() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume()
      return true
    }
    const AC = window.AudioContext || window.webkitAudioContext
    if (!AC) return false
    this.ctx = new AC()
    this.master = this.ctx.createGain()
    this.master.gain.value = this.enabled ? 0.85 : 0
    const comp = this.ctx.createDynamicsCompressor()
    comp.threshold.value = -18
    comp.knee.value = 18
    comp.ratio.value = 3
    comp.attack.value = 0.003
    comp.release.value = 0.25
    this.master.connect(comp).connect(this.ctx.destination)
    this.musicGain = this.ctx.createGain(); this.musicGain.gain.value = 0.21; this.musicGain.connect(this.master)
    this.sfxGain = this.ctx.createGain(); this.sfxGain.gain.value = 0.6; this.sfxGain.connect(this.master)
    this.ambientGain = this.ctx.createGain(); this.ambientGain.gain.value = 0.3; this.ambientGain.connect(this.master)
    this.noiseBuffer = this.makeNoise(2)
    return true
  }

  makeNoise(seconds) {
    const len = Math.floor(this.ctx.sampleRate * seconds)
    const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate)
    const data = buffer.getChannelData(0)
    let last = 0
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1
      last = (last + 0.02 * white) / 1.02
      data[i] = last * 3.5
    }
    return buffer
  }

  start() {
    if (!this.ensure() || this.started) return
    this.started = true
    this.startAmbience()
    this.startMusic()
    this.scheduleBirds()
  }

  setEnabled(on) {
    this.enabled = on
    localStorage.setItem('soulyard-muted', on ? '0' : '1')
    if (this.ensure()) {
      const t = this.ctx.currentTime
      this.master.gain.cancelScheduledValues(t)
      this.master.gain.setTargetAtTime(on ? 0.85 : 0, t, 0.08)
    }
    if (on) this.start()
  }

  toggle() {
    this.setEnabled(!this.enabled)
    return this.enabled
  }

  // ------------------------------------------------------------------ AMBIENCE
  startAmbience() {
    if (this.ambienceStarted) return
    this.ambienceStarted = true
    const ctx = this.ctx
    // Ocean / trade wind bed.
    const src = ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    src.loop = true
    const lp = ctx.createBiquadFilter()
    lp.type = 'lowpass'; lp.frequency.value = 620; lp.Q.value = 0.4
    const waveGain = ctx.createGain(); waveGain.gain.value = 0.22
    const lfo = ctx.createOscillator(); lfo.frequency.value = 0.09
    const lfoGain = ctx.createGain(); lfoGain.gain.value = 0.12
    lfo.connect(lfoGain).connect(waveGain.gain)
    src.connect(lp).connect(waveGain).connect(this.ambientGain)
    src.start(); lfo.start()
    // High breeze.
    const src2 = ctx.createBufferSource(); src2.buffer = this.noiseBuffer; src2.loop = true
    const hp = ctx.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 1800
    const g2 = ctx.createGain(); g2.gain.value = 0.035
    const lfo2 = ctx.createOscillator(); lfo2.frequency.value = 0.05
    const lg2 = ctx.createGain(); lg2.gain.value = 0.025
    lfo2.connect(lg2).connect(g2.gain)
    src2.connect(hp).connect(g2).connect(this.ambientGain)
    src2.start(); lfo2.start()
  }

  scheduleBirds() {
    if (this.birdTimer) return
    const chirp = () => {
      if (this.enabled && this.ctx?.state === 'running' && Math.random() < 0.75) this.bird()
      this.birdTimer = setTimeout(chirp, 2600 + Math.random() * 6500)
    }
    this.birdTimer = setTimeout(chirp, 2200)
  }

  bird() {
    const ctx = this.ctx, t = ctx.currentTime
    const pan = ctx.createStereoPanner ? ctx.createStereoPanner() : null
    if (pan) { pan.pan.value = Math.random() * 1.6 - 0.8; pan.connect(this.ambientGain) }
    const notes = 2 + Math.floor(Math.random() * 3)
    for (let i = 0; i < notes; i++) {
      const o = ctx.createOscillator(); o.type = 'sine'
      const g = ctx.createGain()
      const start = t + i * 0.09 + Math.random() * 0.03
      const f = 1700 + Math.random() * 1400
      o.frequency.setValueAtTime(f, start)
      o.frequency.exponentialRampToValueAtTime(f * (1.2 + Math.random() * 0.5), start + 0.07)
      o.frequency.exponentialRampToValueAtTime(f * 0.8, start + 0.12)
      g.gain.setValueAtTime(0, start)
      g.gain.linearRampToValueAtTime(0.055, start + 0.012)
      g.gain.exponentialRampToValueAtTime(0.0001, start + 0.16)
      o.connect(g); if (pan) g.connect(pan); else g.connect(this.ambientGain)
      o.start(start); o.stop(start + 0.2)
    }
  }

  // ------------------------------------------------------------------ MUSIC
  startMusic() {
    if (this.musicTimer) return
    this.nextStep = this.ctx.currentTime + 0.2
    this.step = 0
    this.musicTimer = setInterval(() => this.scheduleMusic(), 90)
  }

  scheduleMusic() {
    if (!this.ctx || this.ctx.state !== 'running') return
    const spb = 60 / this.bpm / 2 // eighth notes
    while (this.nextStep < this.ctx.currentTime + 0.28) {
      this.playStep(this.step, this.nextStep)
      this.nextStep += spb
      this.step = (this.step + 1) % 64
    }
  }

  playStep(step, t) {
    // Relaxed 8-bar island groove in A minor.
    const bar = Math.floor(step / 8)
    const s = step % 8
    const chords = [
      [57, 60, 64, 67], // Am7
      [53, 57, 60, 64], // Fmaj7
      [48, 55, 60, 64], // Cmaj7
      [55, 59, 62, 65], // G7
      [57, 60, 64, 67],
      [50, 53, 57, 60], // Dm7
      [53, 57, 60, 64],
      [55, 59, 62, 64], // G6
    ]
    const chord = chords[bar]
    // Bass.
    if (s === 0 || s === 5) {
      const n = chord[0] - 12
      this.tone(NOTE(n), t, 0.5, 'sine', 0.2, 280)
      this.tone(NOTE(n), t, 0.4, 'triangle', 0.055, 500)
    }
    if (s === 3) this.tone(NOTE(chord[0] - 5), t, 0.24, 'sine', 0.08, 320)
    // Skank chord stabs on offbeats.
    if (s === 2 || s === 6) {
      chord.slice(1).forEach((n, i) => this.tone(NOTE(n + 12), t + i * 0.004, 0.1, 'triangle', 0.025, 1800))
    }
    // Steel-drum melody, sparse and singable.
    const melodies = [
      [76, null, 79, null, 81, null, 79, null],
      [72, null, 76, 77, null, 76, null, 72],
      [79, null, 81, null, 84, 81, 79, null],
      [74, 76, null, 79, null, 76, 74, null],
      [76, 79, null, 81, null, null, 79, 76],
      [69, null, 72, null, 74, 76, null, null],
      [72, null, 74, 76, null, 79, null, 81],
      [79, null, 77, null, 74, null, 72, null],
    ]
    const note = melodies[bar][s]
    if (note) this.steelDrum(NOTE(note), t, 0.32 + (s % 2) * 0.1)
    // Shaker.
    if (s % 2 === 1 || s === 4) this.shaker(t, s === 4 ? 0.05 : 0.028)
    // Soft kick / heartbeat.
    if (s === 0 || s === 4) this.kick(t, s === 0 ? 0.18 : 0.1)
    // Occasional echo pluck.
    if (step % 16 === 14) this.tone(NOTE(chord[2] + 12), t + 0.15, 0.5, 'sine', 0.03, 2600)
  }

  tone(freq, t, dur, type = 'sine', vol = 0.1, cutoff = 2000) {
    const ctx = this.ctx
    const o = ctx.createOscillator(); o.type = type; o.frequency.value = freq
    const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = cutoff
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), t + 0.012)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    o.connect(f).connect(g).connect(this.musicGain)
    o.start(t); o.stop(t + dur + 0.05)
  }

  steelDrum(freq, t, dur) {
    const ctx = this.ctx
    const carrier = ctx.createOscillator(); carrier.type = 'sine'; carrier.frequency.value = freq
    const mod = ctx.createOscillator(); mod.type = 'sine'; mod.frequency.value = freq * 2.01
    const modGain = ctx.createGain(); modGain.gain.setValueAtTime(freq * 1.8, t); modGain.gain.exponentialRampToValueAtTime(freq * 0.2, t + 0.18)
    mod.connect(modGain).connect(carrier.frequency)
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(0.12, t + 0.008)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    const pan = ctx.createStereoPanner ? ctx.createStereoPanner() : null
    if (pan) { pan.pan.value = Math.sin(t * 0.4) * 0.3; carrier.connect(g).connect(pan).connect(this.musicGain) }
    else carrier.connect(g).connect(this.musicGain)
    carrier.start(t); mod.start(t); carrier.stop(t + dur + 0.1); mod.stop(t + dur + 0.1)
  }

  shaker(t, vol) {
    const ctx = this.ctx
    const src = ctx.createBufferSource(); src.buffer = this.noiseBuffer
    const hp = ctx.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 4800
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(vol, t + 0.005)
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.09)
    src.connect(hp).connect(g).connect(this.musicGain)
    src.start(t, Math.random()); src.stop(t + 0.1)
  }

  kick(t, vol) {
    const ctx = this.ctx
    const o = ctx.createOscillator(); o.type = 'sine'
    o.frequency.setValueAtTime(120, t)
    o.frequency.exponentialRampToValueAtTime(44, t + 0.13)
    const g = ctx.createGain()
    g.gain.setValueAtTime(vol, t)
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.16)
    o.connect(g).connect(this.musicGain)
    o.start(t); o.stop(t + 0.18)
  }

  // ------------------------------------------------------------------ SFX
  now() { return this.ctx?.currentTime ?? 0 }

  sfx(kind) {
    if (!this.enabled || !this.ensure()) return
    const t = this.ctx.currentTime
    const ctx = this.ctx
    switch (kind) {
      case 'shoot': {
        if (t - this._lastShot < 0.03) return
        this._lastShot = t
        const o = ctx.createOscillator(); o.type = 'square'
        o.frequency.setValueAtTime(680 + Math.random() * 120, t)
        o.frequency.exponentialRampToValueAtTime(190, t + 0.075)
        const g = ctx.createGain(); g.gain.setValueAtTime(0.11, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.09)
        const f = ctx.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = 900; f.Q.value = 1.4
        o.connect(f).connect(g).connect(this.sfxGain); o.start(t); o.stop(t + 0.1)
        break
      }
      case 'hit': {
        const o = ctx.createOscillator(); o.type = 'triangle'
        o.frequency.setValueAtTime(210, t); o.frequency.exponentialRampToValueAtTime(70, t + 0.1)
        const g = ctx.createGain(); g.gain.setValueAtTime(0.18, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.12)
        o.connect(g).connect(this.sfxGain); o.start(t); o.stop(t + 0.14)
        break
      }
      case 'crit': {
        const o = ctx.createOscillator(); o.type = 'sawtooth'
        o.frequency.setValueAtTime(520, t); o.frequency.exponentialRampToValueAtTime(140, t + 0.13)
        const g = ctx.createGain(); g.gain.setValueAtTime(0.12, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.15)
        o.connect(g).connect(this.sfxGain); o.start(t); o.stop(t + 0.17)
        break
      }
      case 'hurt': {
        const o = ctx.createOscillator(); o.type = 'sawtooth'
        o.frequency.setValueAtTime(120, t); o.frequency.exponentialRampToValueAtTime(55, t + 0.22)
        const g = ctx.createGain(); g.gain.setValueAtTime(0.16, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.24)
        o.connect(g).connect(this.sfxGain); o.start(t); o.stop(t + 0.26)
        break
      }
      case 'dash': {
        const src = ctx.createBufferSource(); src.buffer = this.noiseBuffer
        const bp = ctx.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.setValueAtTime(300, t); bp.frequency.exponentialRampToValueAtTime(1800, t + 0.22); bp.Q.value = 0.9
        const g = ctx.createGain(); g.gain.setValueAtTime(0.1, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.25)
        src.connect(bp).connect(g).connect(this.sfxGain); src.start(t); src.stop(t + 0.3)
        break
      }
      case 'jump': {
        const o = ctx.createOscillator(); o.type = 'sine'
        o.frequency.setValueAtTime(220, t); o.frequency.exponentialRampToValueAtTime(480, t + 0.12)
        const g = ctx.createGain(); g.gain.setValueAtTime(0.06, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.14)
        o.connect(g).connect(this.sfxGain); o.start(t); o.stop(t + 0.16)
        break
      }
      case 'orb': {
        const src = ctx.createBufferSource(); src.buffer = this.noiseBuffer
        const bp = ctx.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.setValueAtTime(500, t); bp.frequency.exponentialRampToValueAtTime(2400, t + 0.3); bp.Q.value = 1.2
        const g = ctx.createGain(); g.gain.setValueAtTime(0.09, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.32)
        src.connect(bp).connect(g).connect(this.sfxGain); src.start(t); src.stop(t + 0.35)
        const o = ctx.createOscillator(); o.type = 'sine'; o.frequency.setValueAtTime(600, t); o.frequency.exponentialRampToValueAtTime(900, t + 0.25)
        const g2 = ctx.createGain(); g2.gain.setValueAtTime(0.04, t); g2.gain.exponentialRampToValueAtTime(0.0001, t + 0.3)
        o.connect(g2).connect(this.sfxGain); o.start(t); o.stop(t + 0.32)
        break
      }
      case 'capture': {
        const notes = [64, 69, 72, 76, 81]
        notes.forEach((n, i) => {
          const o = ctx.createOscillator(); o.type = i % 2 ? 'sine' : 'triangle'; o.frequency.value = NOTE(n)
          const g = ctx.createGain(); const st = t + i * 0.085
          g.gain.setValueAtTime(0.0001, st); g.gain.exponentialRampToValueAtTime(0.1, st + 0.015); g.gain.exponentialRampToValueAtTime(0.0001, st + 0.7)
          o.connect(g).connect(this.sfxGain); o.start(st); o.stop(st + 0.75)
        })
        break
      }
      case 'levelup': {
        [57, 60, 64, 69, 72, 76].forEach((n, i) => {
          const o = ctx.createOscillator(); o.type = 'sine'; o.frequency.value = NOTE(n)
          const g = ctx.createGain(); const st = t + i * 0.07
          g.gain.setValueAtTime(0.0001, st); g.gain.exponentialRampToValueAtTime(0.08, st + 0.02); g.gain.exponentialRampToValueAtTime(0.0001, st + 0.55)
          o.connect(g).connect(this.sfxGain); o.start(st); o.stop(st + 0.6)
        })
        break
      }
      case 'quest': {
        [69, 72, 76, 81].forEach((n, i) => {
          const o = ctx.createOscillator(); o.type = 'triangle'; o.frequency.value = NOTE(n)
          const g = ctx.createGain(); const st = t + i * 0.11
          g.gain.setValueAtTime(0.0001, st); g.gain.exponentialRampToValueAtTime(0.06, st + 0.02); g.gain.exponentialRampToValueAtTime(0.0001, st + 0.9)
          o.connect(g).connect(this.sfxGain); o.start(st); o.stop(st + 0.95)
        })
        break
      }
      case 'ui': {
        const o = ctx.createOscillator(); o.type = 'sine'; o.frequency.value = 660
        const g = ctx.createGain(); g.gain.setValueAtTime(0.04, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.07)
        o.connect(g).connect(this.sfxGain); o.start(t); o.stop(t + 0.08)
        break
      }
      case 'boss': {
        const o = ctx.createOscillator(); o.type = 'sawtooth'
        o.frequency.setValueAtTime(68, t); o.frequency.exponentialRampToValueAtTime(38, t + 1.1)
        const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.setValueAtTime(320, t); f.frequency.exponentialRampToValueAtTime(90, t + 1.2)
        const g = ctx.createGain(); g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(0.18, t + 0.08); g.gain.exponentialRampToValueAtTime(0.0001, t + 1.4)
        o.connect(f).connect(g).connect(this.sfxGain); o.start(t); o.stop(t + 1.5)
        break
      }
      case 'death': {
        [57, 55, 52, 48].forEach((n, i) => {
          const o = ctx.createOscillator(); o.type = 'sine'; o.frequency.value = NOTE(n)
          const g = ctx.createGain(); const st = t + i * 0.18
          g.gain.setValueAtTime(0.0001, st); g.gain.exponentialRampToValueAtTime(0.08, st + 0.03); g.gain.exponentialRampToValueAtTime(0.0001, st + 1.2)
          o.connect(g).connect(this.sfxGain); o.start(st); o.stop(st + 1.3)
        })
        break
      }
      case 'heal': {
        [72, 76, 79].forEach((n, i) => {
          const o = ctx.createOscillator(); o.type = 'sine'; o.frequency.value = NOTE(n)
          const g = ctx.createGain(); const st = t + i * 0.06
          g.gain.setValueAtTime(0.0001, st); g.gain.exponentialRampToValueAtTime(0.05, st + 0.02); g.gain.exponentialRampToValueAtTime(0.0001, st + 0.45)
          o.connect(g).connect(this.sfxGain); o.start(st); o.stop(st + 0.5)
        })
        break
      }
    }
  }
}

import { clamp } from './utils.js'

const MOVE_KEYS = new Set(['KeyW', 'KeyA', 'KeyS', 'KeyD', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'])

export class Input {
  constructor(game) {
    this.game = game
    this.keys = new Set()
    this.fireHeld = false
    this.firePressed = false
    this.orbPressed = false
    this.jumpPressed = false
    this.dashPressed = false
    this.pulsePressed = false
    this.interactPressed = false
    this.codexPressed = false
    this.pausePressed = false
    this.mutePressed = false
    this.slotPressed = -1
    this.lookDX = 0
    this.lookDY = 0
    this.pointerLocked = false
    this.enabled = false
    this.isTouch = window.matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window
    this.joy = { active: false, pointerId: null, x: 0, y: 0 }
    this.touchLook = { active: false, id: null, x: 0, y: 0 }
    this.touchFire = false
    this._bound = []
    this.bindKeyboard()
    this.bindMouse()
    this.bindTouch()
  }

  bindKeyboard() {
    const down = (e) => {
      if (e.code === 'Tab' || e.code === 'Space') e.preventDefault()
      if (e.repeat) return
      this.keys.add(e.code)
      if (e.code === 'KeyE') this.orbPressed = true
      if (e.code === 'KeyF') this.interactPressed = true
      if (e.code === 'Space') this.jumpPressed = true
      if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') this.dashPressed = true
      if (e.code === 'KeyQ') this.pulsePressed = true
      if (e.code === 'Tab') this.codexPressed = true
      if (e.code === 'Escape') this.pausePressed = true
      if (e.code === 'KeyM') this.mutePressed = true
      if (e.code === 'KeyH') this.pausePressed = true
      if (e.code.startsWith('Digit')) {
        const n = Number(e.code.slice(5))
        if (n >= 1 && n <= 4) this.slotPressed = n - 1
      }
      if (e.code === 'KeyP') this.pausePressed = true
    }
    const up = (e) => { this.keys.delete(e.code) }
    window.addEventListener('keydown', down)
    window.addEventListener('keyup', up)
    this._bound.push(() => window.removeEventListener('keydown', down), () => window.removeEventListener('keyup', up))
  }

  bindMouse() {
    const canvas = this.game.canvas
    const down = (e) => {
      if (!this.enabled) return
      if (e.button === 0) { this.fireHeld = true; this.firePressed = true }
      if (e.button === 2) this.orbPressed = true
      if (this.isTouch) return
      if (!this.pointerLocked && document.pointerLockElement !== canvas) {
        this.requestLock()
      }
    }
    const up = (e) => { if (e.button === 0) this.fireHeld = false }
    const move = (e) => {
      if (!this.enabled || this.isTouch) return
      if (this.pointerLocked) {
        this.lookDX += e.movementX || 0
        this.lookDY += e.movementY || 0
      }
    }
    const context = (e) => e.preventDefault()
    canvas.addEventListener('pointerdown', down)
    window.addEventListener('pointerup', up)
    document.addEventListener('mousemove', move)
    canvas.addEventListener('contextmenu', context)
    const lock = () => {
      this.pointerLocked = document.pointerLockElement === canvas
      if (!this.pointerLocked) this.fireHeld = false
      this.game.onPointerLock?.(this.pointerLocked)
    }
    document.addEventListener('pointerlockchange', lock)
    this._bound.push(
      () => canvas.removeEventListener('pointerdown', down),
      () => window.removeEventListener('pointerup', up),
      () => document.removeEventListener('mousemove', move),
      () => canvas.removeEventListener('contextmenu', context),
      () => document.removeEventListener('pointerlockchange', lock),
    )
  }

  bindTouch() {
    const canvas = this.game.canvas
    const joy = document.getElementById('joystick')
    const knob = joy?.querySelector('.stick-knob')
    if (joy) {
      const radius = 46
      const center = () => {
        const r = joy.getBoundingClientRect()
        return { x: r.left + r.width / 2, y: r.top + r.height / 2 }
      }
      const update = (e) => {
        const c = center()
        let dx = e.clientX - c.x
        let dy = e.clientY - c.y
        const len = Math.hypot(dx, dy)
        if (len > radius) { dx = dx / len * radius; dy = dy / len * radius }
        this.joy.x = dx / radius
        this.joy.y = dy / radius
        knob.style.transform = `translate(${dx}px, ${dy}px)`
      }
      const down = (e) => {
        e.preventDefault()
        this.joy.active = true; this.joy.pointerId = e.pointerId
        joy.setPointerCapture?.(e.pointerId)
        update(e)
      }
      const move = (e) => { if (this.joy.active && e.pointerId === this.joy.pointerId) update(e) }
      const up = (e) => {
        if (e.pointerId !== this.joy.pointerId) return
        this.joy.active = false; this.joy.pointerId = null; this.joy.x = 0; this.joy.y = 0
        knob.style.transform = ''
      }
      joy.addEventListener('pointerdown', down)
      joy.addEventListener('pointermove', move)
      joy.addEventListener('pointerup', up)
      joy.addEventListener('pointercancel', up)
    }

    // Look drag anywhere on the canvas (touch devices).
    const down = (e) => {
      if (!this.enabled || !this.isTouch) return
      if (e.pointerType === 'mouse') return
      if (this.touchLook.active) return
      this.touchLook.active = true; this.touchLook.id = e.pointerId
      this.touchLook.x = e.clientX; this.touchLook.y = e.clientY
      canvas.setPointerCapture?.(e.pointerId)
    }
    const move = (e) => {
      if (!this.touchLook.active || e.pointerId !== this.touchLook.id) return
      const dx = e.clientX - this.touchLook.x
      const dy = e.clientY - this.touchLook.y
      this.lookDX += dx * 1.8
      this.lookDY += dy * 1.8
      this.touchLook.x = e.clientX; this.touchLook.y = e.clientY
    }
    const up = (e) => {
      if (e.pointerId !== this.touchLook.id) return
      this.touchLook.active = false; this.touchLook.id = null
    }
    canvas.addEventListener('pointerdown', down)
    canvas.addEventListener('pointermove', move)
    window.addEventListener('pointerup', up)
    window.addEventListener('pointercancel', up)
    this._bound.push(
      () => canvas.removeEventListener('pointerdown', down),
      () => canvas.removeEventListener('pointermove', move),
      () => window.removeEventListener('pointerup', up),
      () => window.removeEventListener('pointercancel', up),
    )

    const hold = (id, onDown, onUp) => {
      const el = document.getElementById(id)
      if (!el) return
      const d = (e) => { e.preventDefault(); e.stopPropagation(); onDown?.() }
      const u = (e) => { e.preventDefault(); e.stopPropagation(); onUp?.() }
      el.addEventListener('pointerdown', d)
      el.addEventListener('pointerup', u)
      el.addEventListener('pointercancel', u)
      el.addEventListener('pointerleave', u)
      this._bound.push(() => { el.removeEventListener('pointerdown', d); el.removeEventListener('pointerup', u); el.removeEventListener('pointercancel', u); el.removeEventListener('pointerleave', u) })
    }
    hold('btn-fire', () => { this.fireHeld = true; this.firePressed = true }, () => { this.fireHeld = false })
    hold('btn-orb', () => { this.orbPressed = true })
    hold('btn-jump', () => { this.jumpPressed = true })
    hold('btn-dash', () => { this.dashPressed = true })
    hold('btn-pulse', () => { this.pulsePressed = true })
    hold('btn-bonds', () => { this.codexPressed = true })
    hold('btn-talk', () => { this.interactPressed = true })
  }

  requestLock() {
    const canvas = this.game.canvas
    if (this.isTouch) return
    try { canvas.requestPointerLock?.() } catch {}
  }

  exitLock() {
    if (document.pointerLockElement) document.exitPointerLock?.()
  }

  setEnabled(on) {
    this.enabled = on
    if (!on) { this.fireHeld = false; this.keys.clear(); this.joy.x = 0; this.joy.y = 0; this.lookDX = 0; this.lookDY = 0 }
  }

  consumeLook() {
    const dx = this.lookDX, dy = this.lookDY
    this.lookDX = 0; this.lookDY = 0
    return [dx, dy]
  }

  consume(name) {
    if (!this[name]) return false
    this[name] = false
    return true
  }

  consumeSlot() {
    const s = this.slotPressed
    this.slotPressed = -1
    return s
  }

  get moveX() {
    let x = 0
    if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) x += 1
    if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) x -= 1
    x += this.joy.x
    return clamp(x, -1, 1)
  }

  get moveY() {
    let y = 0
    if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) y += 1
    if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) y -= 1
    y += this.joy.y
    return clamp(y, -1, 1)
  }

  get fire() { return this.fireHeld || this.touchFire }

  endFrame() {
    this.firePressed = false
    this.orbPressed = false
    this.jumpPressed = false
    this.dashPressed = false
    this.pulsePressed = false
    this.interactPressed = false
    this.codexPressed = false
    this.pausePressed = false
    this.mutePressed = false
    this.slotPressed = -1
  }

  dispose() { this._bound.forEach(fn => fn()) }
}

import * as THREE from 'three'
import { CAPTURE_THRESHOLD, CREATURE_BY_ID, typeMultiplier } from './constants.js'
import { buildCreature } from './models.js'
import { angleLerp, clamp, damp, dist2D, glowSprite, lerp, mulberry32, range, TAU } from './utils.js'
import { isWater, terrainHeight } from './terrain.js'

let nextId = 1

export class Creature {
  constructor(def, opts = {}) {
    this.id = nextId++
    this.def = def
    this.game = opts.game
    this.scene = opts.scene
    this.level = opts.level ?? 3
    this.boss = !!opts.boss
    this.bossDef = opts.bossDef ?? null
    this.final = !!opts.final
    this.friendly = !!opts.friendly
    this.minion = !!opts.minion
    this.home = new THREE.Vector3(opts.x ?? 0, 0, opts.z ?? 0)
    this.home.y = terrainHeight(this.home.x, this.home.z)
    this.baseY = this.home.y
    this.fly = !!def.stats.fly
    this.moveSpeed = def.stats.speed * (1 + this.level * 0.012)
    this.aggressive = !opts.passive

    const scale = opts.scale ?? (this.boss ? (this.bossDef?.scale ?? 2.4) : def.stats.scale)
    this.model = buildCreature(def, { boss: this.boss, scale })
    this.model.position.copy(this.home)
    this.scene.add(this.model)
    this.scale = scale
    this.hitRadius = (this.model.userData.radius ?? 1) * scale * 0.82
    this.height = (this.model.userData.height ?? 2) * scale
    this.baseScale = scale

    const multiplier = 1 + (this.level - 1) * 0.11
    this.maxHp = this.boss ? this.bossDef.hp : Math.round(def.stats.hp * multiplier)
    this.hp = this.maxHp
    this.damage = (this.boss ? 14 : def.stats.damage) * (1 + this.level * 0.035)
    this.state = this.boss ? 'dormant' : 'idle'
    this.dormant = this.boss
    this.stateTime = 0
    this.attackCooldown = 0.8 + Math.random() * 1.6
    this.attackWindup = 0
    this.captureReady = false
    this.captureThreshold = CAPTURE_THRESHOLD + (opts.captureBonus ?? 0)
    this.dead = false
    this.captured = false
    this.weakened = false
    this.hitFlash = 0
    this.burn = 0
    this.burnTick = 0
    this.slow = 0
    this.mark = 0
    this.stun = 0
    this.wander = { x: this.home.x, z: this.home.z, timer: 0 }
    this.facing = Math.random() * TAU
    this.velocity = new THREE.Vector3()
    this.speedNow = 0
    this.attackAnim = 0
    this.bossPhase = 1
    this.patternTimer = 2.5
    this.chargeTimer = 0
    this.leash = this.boss ? 30 : 24
    this.flashMats = []
    this.originalEmissive = new Map()
    this.model.traverse(o => {
      if (o.isMesh && o.material && o.material.emissive) {
        o.material = o.material.clone()
        this.flashMats.push(o.material)
        this.originalEmissive.set(o.material, { color: o.material.emissive.clone(), intensity: o.material.emissiveIntensity })
      }
    })

    // Detach the health bar from the scaled model so it stays screen-readable.
    this.bar = this.model.userData.bar
    if (this.bar) {
      this.model.remove(this.bar)
      this.scene.add(this.bar)
      this.bar.position.copy(this.model.position).setY(this.model.position.y + this.height + 0.55)
    }

    this.captureRing = new THREE.Mesh(
      new THREE.RingGeometry(this.hitRadius * 1.1, this.hitRadius * 1.24, 32),
      new THREE.MeshBasicMaterial({ color: 0xf4c95d, transparent: true, opacity: 0, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending }),
    )
    this.captureRing.rotation.x = -Math.PI / 2
    this.scene.add(this.captureRing)

    this.aggroRange = this.boss ? 26 : 15
    this.shadow = null
    this.updateBar()
  }

  get alive() { return !this.dead && !this.captured && !this.weakened }
  get hpRatio() { return this.hp / this.maxHp }
  get type() { return this.def.type }
  get name() { return this.boss ? this.bossDef.name : this.def.name }
  get levelLabel() { return `LV ${this.level}` }

  updateBar() {
    if (!this.bar) return
    const fill = this.bar.userData.fill
    if (!fill) return
    const ratio = clamp(this.hp / this.maxHp, 0, 1)
    fill.scale.x = Math.max(0.001, ratio)
    fill.position.x = -(1 - ratio) / 2
    const mat = fill.material
    if (this.captureReady) mat.color.setHex(0xf4c95d)
    else if (this.boss) mat.color.setHex(0xff5d54)
    else mat.color.setHex(0xff6b4a)
    this.bar.visible = !this.dead && !this.captured && (this.boss || this.hp < this.maxHp || this.state === 'aggro' || this.captureReady)
  }

  setDormant(value) {
    this.dormant = value
    this.state = value ? 'dormant' : 'idle'
  }

  awaken() {
    this.dormant = false
    this.state = 'aggro'
    this.attackCooldown = 1.2
    this.patternTimer = 2.4
    this.game.audio.sfx('boss')
    this.game.hud.toast('warden awakened', 'The shrine stone cracks.', 'coral')
  }

  takeDamage(amount, type = 'aether', opts = {}) {
    if (!this.alive || this.dormant) return { damage: 0, crit: false, mult: 1 }
    const mult = typeMultiplier(type, this.type)
    let dmg = amount * mult
    if (this.mark > 0) dmg *= 1.15
    if (this.def.stats.build === 'lion') dmg *= 0.9
    const crit = Math.random() < (opts.critChance ?? 0.09)
    if (crit) dmg *= 1.65
    dmg = Math.max(1, Math.round(dmg))
    if (this.captureReady) {
      this.hp = Math.max(1, this.hp - dmg * 0.1)
    } else {
      this.hp = Math.max(0, this.hp - dmg)
    }
    this.hitFlash = 0.13
    this.flash()
    this.stateTime = 0
    if (this.state === 'idle' || this.state === 'dormant') this.state = 'aggro'
    this.game.hud.damageNumber(this.worldPos(0, this.height * 0.7), dmg, type, { crit, mult })
    this.game.audio.sfx(crit ? 'crit' : 'hit')
    if (type === 'fire' && !this.captureReady) this.burn = Math.max(this.burn, 3.5)
    if (type === 'shadow') this.game.player.heal(Math.round(dmg * 0.12), true)
    if (type === 'spirit') this.mark = Math.max(this.mark, 5)
    this.updateBar()
    this.checkThreshold()

    if (this.hp <= 0 && !this.captureReady) {
      if (this.boss) this.onBossDown()
      else this.die()
    }
    return { damage: dmg, crit, mult }
  }

  checkThreshold() {
    if (this.boss || this.captureReady) return
    if (this.hpRatio <= this.captureThreshold) {
      this.captureReady = true
      this.hp = Math.max(1, this.hp)
      this.state = 'stagger'
      this.attackWindup = 0
      this.velocity.set(0, 0, 0)
      this.stun = 0.9
      this.game.hud.toast('soul exposed', `${this.def.name} can be bonded with a soul orb.`, 'jade')
      this.game.audio.sfx('quest')
      this.updateBar()
    }
  }

  onBossDown() {
    this.hp = 0
    this.weakened = true
    this.state = 'weakened'
    this.velocity.set(0, 0, 0)
    this.captureReady = true
    this.game.audio.sfx('boss')
    this.game.onBossWeakened?.(this)
    this.bar.visible = true
    this.updateBar()
  }

  flash() {
    for (const m of this.flashMats) {
      const orig = this.originalEmissive.get(m)
      if (!orig) continue
      m.emissive.setHex(0xff5d54)
      m.emissiveIntensity = 1.6
    }
  }

  restoreFlash() {
    for (const m of this.flashMats) {
      const orig = this.originalEmissive.get(m)
      if (!orig) continue
      m.emissive.copy(orig.color)
      m.emissiveIntensity = orig.intensity
    }
  }

  worldPos(dx = 0, dy = 0, dz = 0) {
    return new THREE.Vector3(this.model.position.x + dx, this.model.position.y + dy, this.model.position.z + dz)
  }

  die() {
    if (this.dead) return
    this.dead = true
    this.state = 'dead'
    this.hp = 0
    if (this.bar) this.bar.visible = false
    this.game.burst(this.worldPos(0, this.height * 0.5), this.def.colors.glow, 26, 7)
    this.game.ring(this.worldPos(0, 0.2), this.def.colors.glow, 2.2, 10, 0.55)
    this.game.audio.sfx('hit')
    this.deathTime = 0
    this.game.onCreatureDefeated?.(this)
  }

  capture() {
    if (this.captured) return
    this.captured = true
    this.state = 'captured'
    if (this.bar) this.bar.visible = false
    this.captureRing.material.opacity = 0
    this.captureTime = 0
    this.game.audio.sfx('capture')
    this.game.burst(this.worldPos(0, this.height * 0.55), 0x8ff0ce, 36, 8)
    this.game.ring(this.worldPos(0, 0.3), 0x8ff0ce, 1, 7, 0.7)
  }

  remove() {
    this.scene.remove(this.model)
    if (this.bar) this.scene.remove(this.bar)
    this.scene.remove(this.captureRing)
    this.model.traverse(o => {
      if (o.isMesh) {
        o.geometry?.dispose?.()
        if (Array.isArray(o.material)) o.material.forEach(m => m.dispose?.())
        else o.material?.dispose?.()
      }
      if (o.isSprite) o.material?.dispose?.()
    })
    this.captureRing.geometry.dispose()
    this.captureRing.material.dispose()
    if (this.shadow) { this.scene.remove(this.shadow); this.shadow.geometry.dispose(); this.shadow.material.dispose() }
  }

  damagePlayer(amount) {
    this.game.player.takeDamage(amount, this)
  }

  update(dt, t, game) {
    if (this.captured) {
      this.captureTime += dt
      const k = clamp(this.captureTime / 0.65, 0, 1)
      this.model.scale.setScalar(this.baseScale * (1 - k) * (1 + Math.sin(k * Math.PI) * 0.25))
      this.model.rotation.y += dt * 14
      this.model.position.y += dt * 2.4
      if (k >= 1) { this.model.visible = false; this.removeAfter = true }
      return
    }
    if (this.dead) {
      this.deathTime += dt
      const k = clamp(this.deathTime / 1.1, 0, 1)
      this.model.scale.setScalar(this.baseScale * (1 - k))
      this.model.rotation.y += dt * 3
      this.model.position.y += dt * 0.5
      if (k >= 1) this.removeAfter = true
      return
    }

    if (this.hitFlash > 0) {
      this.hitFlash -= dt
      if (this.hitFlash <= 0) this.restoreFlash()
    }
    if (this.burn > 0) {
      this.burn -= dt
      this.burnTick -= dt
      if (this.burnTick <= 0) {
        this.burnTick = 0.65
        if (this.alive && !this.dormant) {
          const d = Math.round(this.maxHp * 0.012 + 2)
          this.hp = Math.max(this.captureReady ? 1 : 0, this.hp - d)
          this.game.hud.damageNumber(this.worldPos(0, this.height * 0.6), d, 'fire', { dot: true })
          this.updateBar()
          if (this.hp <= 0 && !this.captureReady) this.boss ? this.onBossDown() : this.die()
          this.checkThreshold()
        }
      }
    }
    if (this.slow > 0) this.slow -= dt
    if (this.mark > 0) this.mark -= dt
    if (this.stun > 0) this.stun -= dt
    if (this.attackAnim > 0) this.attackAnim -= dt

    if (this.captureReady) {
      this.captureRing.material.opacity = 0.45 + Math.sin(t * 3.4) * 0.18
      this.captureRing.position.copy(this.model.position).setY(terrainHeight(this.model.position.x, this.model.position.z) + 0.1)
      this.captureRing.scale.setScalar(1 + Math.sin(t * 2.2) * 0.05)
    } else {
      this.captureRing.material.opacity = 0
    }

    if (this.dormant) {
      this.animate(dt, t, 0, false)
      this.updateBarTransform(game.camera)
      return
    }

    if (this.state === 'stagger' || this.weakened) {
      this.animate(dt, t, 0, false)
      this.model.position.y = damp(this.model.position.y, this.baseY + (this.weakened ? 0.2 : 0), 4, dt)
      this.updateBarTransform(game.camera)
      return
    }

    if (this.state === 'idle') {
      this.updateIdle(dt, t, game)
    } else if (this.state === 'aggro') {
      this.updateCombat(dt, t, game)
    }

    // Terrain follow and gentle bob.
    const ground = terrainHeight(this.model.position.x, this.model.position.z)
    const hover = this.fly ? (this.boss ? 2.0 : 1.15) * this.scale : 0
    const targetY = ground + hover + (this.fly ? Math.sin(t * 2.1 + this.id) * 0.12 : 0)
    this.model.position.y = damp(this.model.position.y, targetY, this.fly ? 3 : 10, dt)
    if (!this.fly) {
      this.model.position.y = targetY
    }
    // Out-of-bounds / water guard.
    if (isWater(this.model.position.x, this.model.position.z) && !this.fly) {
      const toHome = new THREE.Vector3(this.home.x - this.model.position.x, 0, this.home.z - this.model.position.z)
      if (toHome.lengthSq() > 0.01) this.model.position.addScaledVector(toHome.normalize(), dt * 2)
    }
    this.animate(dt, t, this.speedNow, this.attackAnim > 0)
    this.updateBarTransform(game.camera)
  }

  updateIdle(dt, t, game) {
    this.speedNow = 0
    const p = game.player.position
    const d = dist2D(this.model.position.x, this.model.position.z, p.x, p.z)
    if (this.aggressive && d < this.aggroRange && Math.abs(p.y - this.model.position.y) < 12) {
      this.state = 'aggro'
      this.attackCooldown = 0.4 + Math.random() * 0.8
      return
    }
    this.wander.timer -= dt
    if (this.wander.timer <= 0) {
      this.wander.timer = 2 + Math.random() * 4
      const a = Math.random() * TAU
      const r = Math.random() * (this.boss ? 4 : 7)
      this.wander.x = this.home.x + Math.cos(a) * r
      this.wander.z = this.home.z + Math.sin(a) * r
    }
    const dx = this.wander.x - this.model.position.x
    const dz = this.wander.z - this.model.position.z
    const len = Math.hypot(dx, dz)
    if (len > 0.4) {
      const sp = this.moveSpeed * 0.22
      this.move(dx / len, dz / len, sp, dt)
      this.speedNow = sp
    }
    this.model.rotation.y = angleLerp(this.model.rotation.y, this.facing, 1 - Math.exp(-5 * dt))
  }

  updateCombat(dt, t, game) {
    const p = game.player.position
    const dx = p.x - this.model.position.x
    const dz = p.z - this.model.position.z
    const d = Math.hypot(dx, dz)
    if (d > this.leash * 1.7) {
      this.state = 'idle'
      this.home.x = this.model.position.x
      this.home.z = this.model.position.z
      if (this.boss) this.game.onBossLeash?.(this)
      return
    }
    this.attackCooldown -= dt
    this.speedNow = 0
    const isRanged = this.def.stats.behavior === 'ranged'
    const desired = isRanged ? (this.boss ? 10 : 7.5) : 2.2 + this.scale
    let moveDir = 0

    if (this.boss) this.updateBoss(dt, t, game, d, dx, dz)
    else if (d > desired) moveDir = 1
    else if (d < desired * 0.65) moveDir = -0.7

    if (moveDir !== 0 && this.stun <= 0) {
      const sp = this.moveSpeed * (this.slow > 0 ? 0.55 : 1) * (moveDir > 0 ? 1 : 0.65)
      this.move(dx / (d || 1), dz / (d || 1), sp * moveDir, dt)
      this.speedNow = Math.abs(sp * moveDir)
    } else {
      this.velocity.multiplyScalar(1 - Math.min(1, dt * 7))
    }

    const face = Math.atan2(-dx, -dz)
    this.model.rotation.y = angleLerp(this.model.rotation.y, face, 1 - Math.exp(-7 * dt))

    if (!this.boss && this.attackCooldown <= 0 && d < (isRanged ? 17 : desired + 2.2) && this.stun <= 0) {
      this.attackCooldown = isRanged ? 2.1 + Math.random() * 1.2 : 1.5 + Math.random() * 0.7
      this.performAttack(game, d, dx, dz, t)
    }
  }

  move(dx, dz, speed, dt) {
    const nx = this.model.position.x + dx * speed * dt
    const nz = this.model.position.z + dz * speed * dt
    if (!isWater(nx, nz) || this.fly) {
      this.model.position.x = nx
      this.model.position.z = nz
    } else {
      // Slide along the shoreline.
      if (!isWater(nx, this.model.position.z)) this.model.position.x = nx
      else if (!isWater(this.model.position.x, nz)) this.model.position.z = nz
    }
    this.facing = Math.atan2(-dx, -dz)
  }

  performAttack(game, d, dx, dz, t) {
    const isRanged = this.def.stats.behavior === 'ranged'
    if (isRanged) {
      this.attackAnim = 0.4
      const from = this.worldPos(0, this.height * 0.55)
      const target = game.player.aimPoint()
      const color = this.def.colors.glow
      const count = this.level > 5 ? 2 : 1
      for (let i = 0; i < count; i++) {
        const dir = target.clone().sub(from).normalize()
        if (count > 1) dir.applyAxisAngle(new THREE.Vector3(0, 1, 0), (i - 0.5) * 0.18)
        game.spawnEnemyOrb(from, dir, { damage: this.damage * 0.7, speed: 13, color, radius: 0.3 * this.scale, homing: this.type === 'shadow' ? 0.4 : 0 })
      }
      game.audio.sfx('orb')
    } else {
      this.attackAnim = 0.55
      this.attackWindup = 0.35
      setTimeout(() => {
        if (!this.alive || this.dormant) return
        const pp = game.player.position
        const dd = dist2D(this.model.position.x, this.model.position.z, pp.x, pp.z)
        if (dd < 3.1 * this.scale) this.damagePlayer(this.damage)
        game.burst(this.worldPos(0, this.height * 0.4), this.def.colors.glow, 10, 4)
      }, 320)
    }
  }

  updateBoss(dt, t, game, d, dx, dz) {
    this.patternTimer -= dt
    const hpRatio = this.hpRatio
    const phase = hpRatio < 0.45 ? 2 : 1
    if (phase !== this.bossPhase) {
      this.bossPhase = phase
      this.game.hud.toast('warden enraged', `${this.bossDef.name} draws deeper on the island.`, 'coral')
      this.game.audio.sfx('boss')
    }
    if (this.patternTimer > 0) return
    const id = this.bossDef.id
    this.patternTimer = (phase === 2 ? 2.1 : 3.2) + Math.random() * 1.1
    const from = this.worldPos(0, this.height * 0.55)
    const target = game.player.aimPoint()

    if (id === 'nian-prime') {
      const roll = Math.random()
      if (roll < 0.42) {
        // Charge + quake.
        this.game.hud.toast('the mountain moves', 'Get clear of the stone circle.', 'coral')
        this.game.addShockwave(this.model.position.x, this.model.position.z, { maxRadius: 13, speed: 10, damage: this.damage * 1.1, color: 0xf4c95d, delay: 0.55 })
        if (phase === 2) this.game.addShockwave(this.model.position.x, this.model.position.z, { maxRadius: 18, speed: 8, damage: this.damage * 0.9, color: 0xffd166, delay: 1.35 })
        this.attackAnim = 1.0
      } else if (roll < 0.75) {
        // Rock volley.
        for (let i = 0; i < 3; i++) {
          const dir = target.clone().sub(from).normalize()
          dir.applyAxisAngle(new THREE.Vector3(0, 1, 0), (i - 1) * 0.2)
          game.spawnEnemyOrb(from, dir, { damage: this.damage * 0.8, speed: 11, color: 0xf4c95d, radius: 0.5, gravity: 2.0, homing: 0 })
        }
        game.audio.sfx('orb')
      } else {
        // Lunge.
        const dir = new THREE.Vector3(dx, 0, dz).normalize()
        this.game.dashBoss(this, dir, 18, 0.45)
        setTimeout(() => {
          if (this.alive) {
            const pp = game.player.position
            if (dist2D(this.model.position.x, this.model.position.z, pp.x, pp.z) < 4.5 * this.scale) this.damagePlayer(this.damage * 1.4)
          }
        }, 430)
      }
    } else if (id === 'bakunawa-prime') {
      const roll = Math.random()
      if (roll < 0.45) {
        // Homing moon orbs.
        const n = phase === 2 ? 5 : 3
        for (let i = 0; i < n; i++) {
          const dir = target.clone().sub(from).normalize()
          dir.applyAxisAngle(new THREE.Vector3(0, 1, 0), (i - (n - 1) / 2) * 0.18)
          game.spawnEnemyOrb(from, dir, { damage: this.damage * 0.7, speed: 9.5, color: 0x9f7bff, radius: 0.42, homing: 1.6 })
        }
        game.audio.sfx('orb')
      } else if (roll < 0.78) {
        // Sweeping beam telegraph.
        this.game.addBeamTelegraph(this.model.position.clone().setY(this.model.position.y + this.height * 0.35), target.clone(), { damage: this.damage * 1.6, color: 0xbdf2ff, width: 1.2, delay: 1.1, duration: 0.5 })
        game.audio.sfx('boss')
      } else {
        // Tide rings.
        this.game.addShockwave(this.model.position.x, this.model.position.z, { maxRadius: 16, speed: 9, damage: this.damage, color: 0x79dcff, delay: 0.3 })
      }
    } else if (id === 'quetzal-prime') {
      const roll = Math.random()
      if (roll < 0.4) {
        // Feather fan.
        const n = phase === 2 ? 9 : 6
        for (let i = 0; i < n; i++) {
          const dir = target.clone().sub(from).normalize()
          dir.applyAxisAngle(new THREE.Vector3(0, 1, 0), (i - (n - 1) / 2) * 0.13)
          game.spawnEnemyOrb(from, dir, { damage: this.damage * 0.65, speed: 16, color: 0x8ff0ce, radius: 0.28 })
        }
        game.audio.sfx('orb')
      } else if (roll < 0.72) {
        // Dive.
        const dir = new THREE.Vector3(dx, 0, dz).normalize()
        this.game.dashBoss(this, dir, 26, 0.38, 4.5)
        this.patternTimer = 2.4
      } else {
        // Cyclone: three expanding rings.
        for (let i = 0; i < 3; i++) {
          this.game.addShockwave(this.model.position.x, this.model.position.z, { maxRadius: 8 + i * 5, speed: 12, damage: this.damage * 0.75, color: 0x8ff0ce, delay: i * 0.24 + 0.2 })
        }
      }
    } else if (id === 'anansi-unbound') {
      const roll = Math.random()
      if (roll < 0.34) {
        // Web barrage that slows.
        const n = phase === 2 ? 7 : 4
        for (let i = 0; i < n; i++) {
          const dir = target.clone().sub(from).normalize()
          dir.applyAxisAngle(new THREE.Vector3(0, 1, 0), (i - (n - 1) / 2) * 0.2)
          game.spawnEnemyOrb(from, dir, { damage: this.damage * 0.7, speed: 12, color: 0x7dffd2, radius: 0.46, slow: 1.2 })
        }
        game.audio.sfx('orb')
      } else if (roll < 0.6) {
        // Summon spiderlings.
        this.game.summonMinions(this, 3)
        game.audio.sfx('boss')
      } else if (roll < 0.82) {
        // Expanding web nova.
        this.game.addShockwave(this.model.position.x, this.model.position.z, { maxRadius: 22, speed: 11, damage: this.damage * 1.2, color: 0xc7a4ff, delay: 0.6, slow: 1.5 })
        if (phase === 2) this.game.addShockwave(this.model.position.x, this.model.position.z, { maxRadius: 26, speed: 8, damage: this.damage, color: 0xf4c95d, delay: 1.2 })
      } else {
        // Teleport and lance.
        const a = Math.random() * TAU
        const r = 11
        this.model.position.set(game.player.position.x + Math.cos(a) * r, this.model.position.y, game.player.position.z + Math.sin(a) * r)
        this.game.burst(this.worldPos(0, this.height * 0.5), 0x7dffd2, 20, 6)
        this.game.addBeamTelegraph(this.model.position.clone().setY(this.model.position.y + this.height * 0.4), target.clone(), { damage: this.damage * 1.2, color: 0x7dffd2, width: 0.8, delay: 0.8, duration: 0.35 })
      }
    }
  }

  animate(dt, t, speed, attacking) {
    this.model.userData.animate?.(t, { speed: speed / this.scale, attacking, moving: speed })
    if (this.model.userData.bossAura) this.model.userData.bossAura.material.opacity = 0.12 + Math.sin(t * 2.4) * 0.05
    if (this.model.userData.bossLight) this.model.userData.bossLight.intensity = 1.7 + Math.sin(t * 3.2) * 0.6
  }

  updateBarTransform(camera) {
    if (!this.bar || this.weakened || this.dead || this.captured) return
    const p = this.model.position
    this.bar.position.set(p.x, p.y + this.height + 0.45, p.z)
    this.bar.quaternion.copy(camera.quaternion)
    this.bar.scale.setScalar(clamp(1.15 * this.scale, 1.0, 2.6))
  }

  getScreenTarget() {
    return { name: this.name, hp: clamp(this.hp / this.maxHp, 0, 1), captureReady: this.captureReady, boss: this.boss }
  }
}

import * as THREE from 'three'
import { PLAYER_BASE, PARTY_MAX, typeMultiplier } from './constants.js'
import { buildCreature, buildPlayer } from './models.js'
import { angleLerp, clamp, damp, distanceTo, lerp, TAU } from './utils.js'
import { isWater, terrainHeight } from './terrain.js'

const UP = new THREE.Vector3(0, 1, 0)

export class Player {
  constructor(game) {
    this.game = game
    this.scene = game.scene
    this.camera = game.camera
    this.root = buildPlayer()
    this.scene.add(this.root)
    this.position = this.root.position
    this.position.set(9, 0, 84)
    this.position.y = terrainHeight(9, 84)
    this.velocityY = 0
    this.grounded = true
    this.yaw = 0.2
    this.pitch = -0.05
    this.bodyYaw = 0.2
    this.aiming = false
    this.fireCooldown = 0
    this.fireBloom = 0
    this.aether = PLAYER_BASE.aether
    this.maxAether = PLAYER_BASE.aether
    this.level = 1
    this.xp = 0
    this.xpNext = 100
    this.maxHp = PLAYER_BASE.hp
    this.hp = PLAYER_BASE.hp
    this.shield = 0
    this.shieldMax = 0
    this.baseSpeed = PLAYER_BASE.speed
    this.damage = PLAYER_BASE.damage
    this.critChance = 0.09
    this.orbs = 4
    this.maxOrbs = 6
    this.orbRecharge = 0
    this.orbsUsed = 0
    this.dashCooldown = 0
    this.dashTime = 0
    this.invuln = 0
    this.lastDamage = -99
    this.lastFire = -99
    this.moving = 0
    this.speedNow = 0
    this.dead = false
    this.deathTime = 0
    this.party = []
    this.activeIndex = -1
    this.companion = null
    this.companionCooldown = 0
    this.companionCooldownMax = 10
    this.companionAttack = 0
    this.captureBonus = 0
    this.passives = {}
    this.cameraShake = 0
    this.cameraDistance = 5.1
    this.recoil = 0
    this.lastStep = 0
    this.respawnPoint = new THREE.Vector3(26, 0, 40)
    this.respawnPoint.y = terrainHeight(26, 40)
    this.trailTimer = 0
    this.lastOrbWarning = -10
    this._tmp = new THREE.Vector3()
    this._ray = new THREE.Raycaster()
    this._screenCenter = new THREE.Vector2(0, 0)
    this.loadoutDirty = true
  }

  get activeBond() { return this.party[this.activeIndex] ?? null }
  get shotType() { return this.activeBond?.def.type ?? 'aether' }
  get shotColor() { return this.activeBond?.def.colors.glow ?? 0x62ffd8 }

  setStart(x, z, yaw = 0.2) {
    this.position.set(x, terrainHeight(x, z), z)
    this.yaw = yaw
    this.bodyYaw = yaw
    this.pitch = -0.08
    this.updateCamera(0, true)
  }

  addBond(bond) {
    if (this.party.length >= PARTY_MAX) {
      this.game.hud.toast('party full', 'Your bonds are full. Visit the codex to study the new spirit.', 'coral')
    } else {
      this.party.push(bond)
      if (this.activeIndex < 0) this.selectBond(this.party.length - 1)
    }
    this.loadoutDirty = true
    this.game.hud.syncParty()
    this.game.hud.syncCodex()
  }

  selectBond(index) {
    if (index < 0 || index >= this.party.length) return false
    if (index === this.activeIndex) return true
    this.activeIndex = index
    this.applyBond()
    this.game.hud.syncParty()
    this.game.hud.syncCompanion()
    this.game.audio.sfx('ui')
    return true
  }

  cycleBond(dir = 1) {
    if (!this.party.length) return
    const next = (this.activeIndex + dir + this.party.length) % this.party.length
    this.selectBond(next)
    this.game.hud.toast('bond changed', `${this.party[next].name} answers your call.`, 'jade')
  }

  applyBond() {
    const bond = this.activeBond
    const oldMaxShield = this.shieldMax
    this.passives = {}
    this.shieldMax = 0
    this.captureBonus = 0
    this.baseSpeed = PLAYER_BASE.speed
    if (!bond) {
      this.shield = 0
      this.companionCooldownMax = 10
      this.spawnCompanion()
      return
    }
    const def = bond.def
    const bonuses = {
      anansi: () => { this.captureBonus = 0.1 },
      calf: () => { this.fireBonus = 0.08 },
      mami: () => { this.passives.regen = 1.2 },
      quetzal: () => { this.baseSpeed *= 1.12 },
      nian: () => { this.shieldMax = 25 },
      bakunawa: () => { this.critChance += 0.08 },
      kitsune: () => { this.passives.aetherRegen = 1.35 },
      raven: () => { this.passives.orbDrop = 1.3 },
    }
    bonuses[def.id]?.()
    if (this.shieldMax > 0) this.shield = Math.max(this.shield, this.shieldMax)
    else if (oldMaxShield > 0) this.shield = Math.min(this.shield, 0)
    this.companionCooldownMax = def.ability.cooldown
    this.companionCooldown = Math.min(this.companionCooldown, this.companionCooldownMax)
    this.spawnCompanion()
    this.loadoutDirty = true
  }

  spawnCompanion() {
    if (this.companion) {
      this.scene.remove(this.companion.model)
      this.companion.model.traverse(o => { if (o.isMesh) { o.geometry?.dispose?.(); o.material?.dispose?.() } if (o.isSprite) o.material?.dispose?.() })
      this.companion = null
    }
    const bond = this.activeBond
    if (!bond) return
    const model = buildCreature(bond.def, { scale: (bond.def.stats.scale ?? 1) * 0.72 })
    model.traverse(o => { if (o.isMesh) o.castShadow = true })
    // Remove the detached health bar that comes with creature models.
    if (model.userData.bar) model.remove(model.userData.bar)
    this.scene.add(model)
    const pos = this.position.clone().add(new THREE.Vector3(-1.8, 0.8, 1.8))
    model.position.copy(pos)
    this.companion = {
      model, def: bond.def, bond,
      follow: pos.clone(), attackTimer: 0.8 + Math.random(),
      bob: Math.random() * TAU, facing: 0,
    }
  }

  update(dt, t, input, game) {
    if (this.dead) {
      this.deathTime += dt
      this.root.visible = this.deathTime < 1.0
      this.updateCamera(dt)
      return
    }

    const [lookDX, lookDY] = input.consumeLook()
    this.yaw -= lookDX * 0.0022
    this.pitch -= lookDY * 0.0019
    this.pitch = clamp(this.pitch, -0.52, 0.62)
    this.yaw = ((this.yaw + Math.PI) % TAU + TAU) % TAU - Math.PI

    if (input.consumeSlot() >= 0) {
      const s = input.consumeSlot()
      if (s >= 0) this.selectBond(s)
    }

    // Movement basis from camera yaw.
    const fx = -Math.sin(this.yaw), fz = -Math.cos(this.yaw)
    const rx = Math.cos(this.yaw), rz = -Math.sin(this.yaw)
    const mx = input.moveX, mz = input.moveY
    let dirX = fx * (-mz) + rx * mx
    let dirZ = fz * (-mz) + rz * mx
    const mag = Math.hypot(dirX, dirZ)
    if (mag > 1) { dirX /= mag; dirZ /= mag }
    const moving = Math.min(1, Math.hypot(dirX, dirZ))
    this.moving = damp(this.moving, moving, 12, dt)
    this.speedNow = moving * this.baseSpeed

    if (this.dashCooldown > 0) this.dashCooldown -= dt
    if (this.invuln > 0) this.invuln -= dt
    if (this.dashTime > 0) {
      this.dashTime -= dt
      const dashSpeed = PLAYER_BASE.dashSpeed
      this.tryMove(dirX * dashSpeed * dt, dirZ * dashSpeed * dt)
      this.trailTimer -= dt
      if (this.trailTimer <= 0) {
        this.trailTimer = 0.045
        game.spawnDashTrail(this.position.clone().add(new THREE.Vector3(0, 0.9, 0)), this.shotColor)
      }
    } else {
      const speed = this.baseSpeed * (this.passives.regen ? 1 : 1)
      if (moving > 0.02) {
        const stepTime = 1 / (3.8 + this.speedNow * 0.3)
        this.lastStep += dt
        if (this.lastStep > stepTime) {
          this.lastStep = 0
          game.audio.sfx('step')
        }
        this.tryMove(dirX * speed * dt, dirZ * speed * dt)
        this.bodyYaw = angleLerp(this.bodyYaw, Math.atan2(-dirX, -dirZ), 1 - Math.exp(-12 * dt))
      }
    }

    if (input.consume('jumpPressed') && this.grounded) {
      this.velocityY = PLAYER_BASE.jump
      this.grounded = false
      game.audio.sfx('jump')
      game.burst(this.position.clone().setY(this.position.y + 0.1), 0xcfe8c4, 8, 2.4)
    }
    if (input.consume('dashPressed') && this.dashCooldown <= 0 && moving > 0.05) {
      this.dashTime = 0.18
      this.dashCooldown = PLAYER_BASE.dashCooldown
      this.invuln = 0.32
      game.audio.sfx('dash')
      game.cameraKick(0.02)
    }

    // Gravity / ground.
    this.velocityY -= 24 * dt
    this.position.y += this.velocityY * dt
    const ground = terrainHeight(this.position.x, this.position.z)
    if (this.position.y <= ground) {
      if (!this.grounded && this.velocityY < -5) game.burst(this.position.clone(), 0xcfe8c4, 7, 2)
      this.position.y = ground
      this.velocityY = 0
      this.grounded = true
    } else {
      this.grounded = false
    }

    // Aiming / firing.
    const wantsAim = input.fire || input.firePressed || (t - this.lastFire < 0.9)
    this.aiming = wantsAim
    if (this.aiming) this.bodyYaw = angleLerp(this.bodyYaw, this.yaw, 1 - Math.exp(-18 * dt))
    if (input.fire) this.tryShoot(dt, t, game)
    if (this.fireCooldown > 0) this.fireCooldown -= dt
    if (this.fireBloom > 0) this.fireBloom = Math.max(0, this.fireBloom - dt * 2.2)
    if (input.consume('orbPressed')) this.throwOrb(game)

    // Aether regen.
    const regen = PLAYER_BASE.aetherRegen * (this.passives.aetherRegen ?? 1)
    this.aether = Math.min(this.maxAether, this.aether + regen * dt)
    // Orb recharge.
    if (this.orbs < 3) {
      this.orbRecharge += dt
      if (this.orbRecharge > 12) {
        this.orbRecharge = 0
        this.orbs++
        game.hud.toast('soul orb recovered', 'The island provides.', 'jade')
        game.audio.sfx('ui')
      }
    } else this.orbRecharge = 0
    // Health regen.
    const outOfCombat = t - this.lastDamage > 6
    if (outOfCombat && this.hp < this.maxHp) this.hp = Math.min(this.maxHp, this.hp + 2.2 * dt)
    if (this.passives.regen) this.hp = Math.min(this.maxHp, this.hp + this.passives.regen * dt)
    // Shield regen.
    if (this.shieldMax > 0 && this.shield < this.shieldMax) {
      this.shield = Math.min(this.shieldMax, this.shield + 2.5 * dt)
    }

    // Companion.
    this.updateCompanion(dt, t, game)
    if (input.consume('pulsePressed')) this.spiritPulse(game)

    // Character animation.
    const airborne = !this.grounded && this.velocityY > 0.5
    this.root.position.copy(this.position)
    this.root.rotation.y = this.bodyYaw
    this.root.userData.animate?.(t, {
      moving: this.moving,
      speed: this.speedNow,
      airborne,
      aiming: this.aiming,
    })
    this.root.visible = this.invuln > 0 ? (Math.floor(t * 30) % 2 === 0) : true

    this.updateCamera(dt)
    this.updateAimUI(game, t)
    this.checkPickups(game)
    this.updateHud(game)
    this.shake = Math.max(0, this.cameraShake - dt * 2.8)
    this.cameraShake = this.shake
    this.recoil = damp(this.recoil, 0, 10, dt)
  }

  tryMove(dx, dz) {
    let nx = this.position.x + dx
    let nz = this.position.z + dz
    const world = this.game.world
    if (isWater(nx, this.position.z)) nx = this.position.x
    if (isWater(this.position.x, nz)) nz = this.position.z
    if (world.isBlocked(nx, this.position.z, 0.38)) nx = this.position.x
    if (world.isBlocked(this.position.x, nz, 0.38)) nz = this.position.z
    const r = Math.hypot(nx, nz)
    if (r > 122) {
      nx = nx / r * 122 * 0.98
      nz = nz / r * 122 * 0.98
    }
    this.position.x = nx
    this.position.z = nz
  }

  cameraBasis() {
    const cp = Math.cos(this.pitch)
    const forward = new THREE.Vector3(-Math.sin(this.yaw) * cp, Math.sin(this.pitch), -Math.cos(this.yaw) * cp)
    const right = new THREE.Vector3(Math.cos(this.yaw), 0, -Math.sin(this.yaw))
    return { forward, right }
  }

  updateCamera(dt, snap = false) {
    const { forward, right } = this.cameraBasis()
    const target = this._tmp.copy(this.position).add(new THREE.Vector3(0, 1.55, 0))
    const desired = new THREE.Vector3().copy(target)
      .addScaledVector(forward, -this.cameraDistance)
      .addScaledVector(right, 0.72)
      .add(new THREE.Vector3(0, 0.35, 0))
    // Prevent the camera from clipping through the island.
    const steps = 10
    let actual = desired
    for (let i = 3; i <= steps; i++) {
      const p = new THREE.Vector3().lerpVectors(target, desired, i / steps)
      if (p.y < terrainHeight(p.x, p.z) + 0.55) {
        actual = new THREE.Vector3().lerpVectors(target, desired, Math.max(0.16, (i - 1) / steps))
        break
      }
    }
    this.camera.position.lerp(actual, snap ? 1 : 1 - Math.exp(-11 * dt))
    if (snap) this.camera.position.copy(actual)
    const shake = this.cameraShake
    if (shake > 0.001) {
      this.camera.position.x += (Math.random() - 0.5) * shake
      this.camera.position.y += (Math.random() - 0.5) * shake
      this.camera.position.z += (Math.random() - 0.5) * shake
    }
    const look = target.clone().addScaledVector(forward, 26)
    look.y += this.recoil * 3.4
    this.camera.lookAt(look)
    const fovTarget = 62 + (this.dashTime > 0 ? 6 : 0) + this.moving * 2
    this.camera.fov = damp(this.camera.fov, fovTarget, 6, dt)
    this.camera.updateProjectionMatrix()
  }

  aimPoint(maxDist = 60) {
    const { forward } = this.cameraBasis()
    const origin = this.camera.position.clone()
    const dir = forward.clone()
    let dist = maxDist
    const step = 1.0
    for (let d = 2; d < maxDist; d += step) {
      const p = origin.clone().addScaledVector(dir, d)
      if (p.y < terrainHeight(p.x, p.z)) { dist = d; break }
    }
    return origin.addScaledVector(dir, Math.min(dist, maxDist))
  }

  raycastAim(game, spread = 0) {
    const { forward } = this.cameraBasis()
    const origin = this.camera.position.clone()
    const dir = forward.clone()
    if (spread) {
      dir.x += (Math.random() - 0.5) * spread
      dir.y += (Math.random() - 0.5) * spread
      dir.z += (Math.random() - 0.5) * spread
      dir.normalize()
    }
    let wall = 90
    for (let d = 1.5; d < 90; d += 0.8) {
      const p = origin.clone().addScaledVector(dir, d)
      if (p.y < terrainHeight(p.x, p.z)) { wall = d; break }
    }
    let hitCreature = null
    let hitDist = wall
    for (const c of game.creatures) {
      if (!c.alive || c.dormant) continue
      const center = c.model.position.clone().add(new THREE.Vector3(0, c.height * 0.55, 0))
      const oc = center.clone().sub(origin)
      const tca = oc.dot(dir)
      if (tca < 0 || tca > wall) continue
      const d2 = oc.lengthSq() - tca * tca
      const r = c.hitRadius * 1.05
      if (d2 <= r * r) {
        const thc = Math.sqrt(Math.max(0, r * r - d2))
        const t0 = tca - thc
        if (t0 < hitDist && t0 > 0.5) { hitDist = t0; hitCreature = c }
      }
    }
    const point = origin.clone().addScaledVector(dir, hitDist)
    return { creature: hitCreature, point, dist: hitDist, origin, dir }
  }

  tryShoot(dt, t, game) {
    if (this.fireCooldown > 0) return
    const cost = PLAYER_BASE.aetherCost
    if (this.aether < cost) {
      if (t - this.lastFire > 0.6) game.hud.toast('aether spent', 'Release the trigger. The gauntlet recharges.', 'coral')
      return
    }
    this.fireCooldown = 1 / PLAYER_BASE.fireRate
    this.aether -= cost
    this.lastFire = t
    this.fireBloom = Math.min(1.5, this.fireBloom + 0.18)
    const spread = 0.012 + this.fireBloom * 0.017 + this.moving * 0.012 + (this.grounded ? 0 : 0.02)
    const shot = this.raycastAim(game, spread)
    const muzzle = new THREE.Vector3()
    this.root.userData.muzzle.getWorldPosition(muzzle)
    game.spawnTracer(muzzle, shot.point, this.shotColor, this.shotType)
    game.burst(shot.point, this.shotColor, 5, 3.2, 0.25)
    game.audio.sfx('shoot')
    this.cameraKick(0.012 + Math.random() * 0.006)
    this.recoil += 0.55
    game.hud.bloom(this.fireBloom)
    if (shot.creature) {
      const dmg = this.damage + (this.activeBond?.level ?? 0) * 0.7
      const result = shot.creature.takeDamage(dmg, this.shotType, { critChance: this.critChance })
      if (result.crit) this.recoil += 0.35
      game.hud.hitmark(result.crit, result.mult > 1.2)
    }
  }

  throwOrb(game) {
    if (this.orbs <= 0) {
      const t = game.time
      if (t - this.lastOrbWarning > 3) {
        this.lastOrbWarning = t
        game.hud.toast('no soul orbs', 'Find a cache, bond a spirit, or wait for a recharge.', 'coral')
        game.audio.sfx('ui')
      }
      return
    }
    this.orbs--
    this.orbRecharge = 0
    game.hud.syncOrbs()
    const { forward } = this.cameraBasis()
    const muzzle = new THREE.Vector3()
    this.root.userData.muzzle.getWorldPosition(muzzle)
    const aim = this.aimPoint(45)
    const dir = aim.clone().sub(muzzle).normalize()
    const velocity = dir.multiplyScalar(27).add(new THREE.Vector3(0, 2.6, 0))
    game.spawnSoulOrb(muzzle.clone().addScaledVector(dir, 0.2), velocity)
    game.audio.sfx('orb')
    this.recoil += 0.2
  }

  spiritPulse(game) {
    const bond = this.activeBond
    if (!bond) {
      game.hud.toast('no bonded spirit', 'Weaken a wild spirit and throw a soul orb to bond it.', 'coral')
      return
    }
    if (this.companionCooldown > 0) {
      game.hud.toast('spirit recovering', `${bond.name} needs ${Math.ceil(this.companionCooldown)}s.`, 'coral')
      return
    }
    const def = bond.def
    this.companionCooldown = this.companionCooldownMax
    const aim = this.aimPoint(30)
    const p = this.position.clone().add(new THREE.Vector3(0, 1.2, 0))
    if (def.ability.heal) {
      this.heal(def.ability.heal)
      game.ring(p.clone().setY(this.position.y + 0.2), def.colors.glow, 1, 10, 0.8)
      game.audio.sfx('heal')
      game.hud.toast('healing spring', `${def.name} mends your spirit.`, 'jade')
      return
    }
    const from = this.companion ? this.companion.model.position.clone().add(new THREE.Vector3(0, 1, 0)) : p
    game.spawnCompanionBeam(from, aim, def.colors.glow, def.type)
    game.ring(aim.clone().setY(terrainHeight(aim.x, aim.z) + 0.15), def.colors.glow, 1, def.ability.radius, 0.75)
    let hits = 0
    for (const c of game.creatures) {
      if (!c.alive || c.dormant) continue
      const d = c.model.position.distanceTo(aim)
      if (d <= def.ability.radius + c.hitRadius) {
        const dmg = (def.ability.damage + bond.level * 1.5) * typeMultiplier(def.type, c.type)
        c.takeDamage(dmg, def.type, { critChance: this.critChance })
        if (def.type === 'air') c.stun = Math.max(c.stun, 0.9)
        if (def.type === 'earth') c.slow = Math.max(c.slow, 1.5)
        if (def.type === 'water') c.slow = Math.max(c.slow, 2)
        hits++
      }
    }
    game.cameraKick(0.06)
    game.audio.sfx('levelup')
    game.hud.toast(`${def.ability.name.toLowerCase()} released`, hits ? `${hits} spirits caught in the pulse.` : 'The energy dissipates.', 'jade')
  }

  updateCompanion(dt, t, game) {
    if (this.companionCooldown > 0) this.companionCooldown = Math.max(0, this.companionCooldown - dt)
    const c = this.companion
    if (!c) return
    const m = c.model
    const target = new THREE.Vector3(
      this.position.x - Math.cos(this.bodyYaw) * 1.7 + Math.sin(this.bodyYaw) * 0.9,
      0,
      this.position.z + Math.sin(this.bodyYaw) * 1.7 + Math.cos(this.bodyYaw) * 0.9,
    )
    const ground = terrainHeight(target.x, target.z)
    target.y = ground + 0.35 + Math.sin(t * 1.8 + c.bob) * 0.14
    const dist = m.position.distanceTo(target)
    if (dist > 26) {
      m.position.copy(target)
      game.burst(target, c.def.colors.glow, 12, 4)
    } else {
      m.position.lerp(target, 1 - Math.exp(-3.8 * dt))
    }
    const away = new THREE.Vector3().subVectors(target, m.position)
    c.speed = away.length() / Math.max(dt, 0.001)
    // Face nearest enemy, otherwise face where the player looks.
    let nearest = null, nd = 24
    for (const e of game.creatures) {
      if (!e.alive || e.dormant) continue
      const d = e.model.position.distanceTo(m.position)
      if (d < nd) { nd = d; nearest = e }
    }
    let face = this.bodyYaw + Math.PI
    if (nearest) face = Math.atan2(-(nearest.model.position.x - m.position.x), -(nearest.model.position.z - m.position.z))
    m.rotation.y = angleLerp(m.rotation.y, face, 1 - Math.exp(-6 * dt))
    c.attackTimer -= dt
    if (nearest && c.attackTimer <= 0) {
      c.attackTimer = 1.75 + Math.random() * 0.7
      const from = m.position.clone().add(new THREE.Vector3(0, 0.9, 0))
      const dmg = 7 + c.bond.level * 1.4
      game.spawnAllyBolt(from, nearest, dmg, c.def.type, c.def.colors.glow)
    }
    m.userData.animate?.(t, { speed: Math.min(6, c.speed), attacking: c.attackTimer > 1.2 })
  }

  takeDamage(amount, source) {
    if (this.dead || this.invuln > 0) return
    let dmg = Math.max(1, Math.round(amount))
    if (this.shield > 0) {
      const absorbed = Math.min(this.shield, dmg)
      this.shield -= absorbed
      dmg -= absorbed
      this.game.hud.damageNumber(this.position.clone().add(new THREE.Vector3(0, 1.7, 0)), absorbed, 'earth', { absorb: true })
    }
    if (dmg > 0) {
      this.hp = Math.max(0, this.hp - dmg)
      this.game.hud.playerHit(dmg)
      this.game.hud.damageNumber(this.position.clone().add(new THREE.Vector3(0, 1.9, 0)), dmg, 'damage', { player: true })
    }
    this.lastDamage = this.game.time
    this.cameraShake = Math.min(0.32, this.cameraShake + 0.12)
    this.game.audio.sfx('hurt')
    if (this.hp <= 0) this.die()
  }

  heal(amount, silent = false) {
    if (this.dead) return
    const before = this.hp
    this.hp = Math.min(this.maxHp, this.hp + amount)
    if (!silent && this.hp > before) {
      this.game.hud.damageNumber(this.position.clone().add(new THREE.Vector3(0, 1.8, 0)), Math.round(this.hp - before), 'heal', { heal: true })
      this.game.audio.sfx('heal')
    }
  }

  die() {
    if (this.dead) return
    this.dead = true
    this.deathTime = 0
    this.aiming = false
    this.game.audio.sfx('death')
    this.game.onPlayerDeath?.(this)
  }

  respawn() {
    this.dead = false
    this.deathTime = 0
    this.hp = this.maxHp
    this.aether = this.maxAether
    this.shield = this.shieldMax
    this.orbs = Math.max(this.orbs, 3)
    this.position.copy(this.respawnPoint)
    this.position.y = terrainHeight(this.position.x, this.position.z)
    this.velocityY = 0
    this.root.visible = true
    this.yaw = 0
    this.invuln = 2
    this.updateCamera(0, true)
    this.spawnCompanion()
    this.game.hud.syncOrbs()
    this.game.hud.syncVitals()
  }

  addXP(amount) {
    this.xp += amount
    while (this.xp >= this.xpNext) {
      this.xp -= this.xpNext
      this.level++
      this.xpNext = Math.round(this.xpNext * 1.32 + 28)
      this.maxHp += 12
      this.hp = this.maxHp
      this.maxAether += 6
      this.damage += 0.9
      this.game.hud.toast('warden level up', `Level ${this.level} · health and aether restored.`, 'jade')
      this.game.audio.sfx('levelup')
      this.game.ring(this.position.clone(), 0xf4c95d, 0.8, 9, 0.9)
      this.game.burst(this.position.clone().add(new THREE.Vector3(0, 1, 0)), 0xf4c95d, 24, 6)
    }
    this.game.hud.syncVitals()
  }

  addOrbs(n = 1) {
    this.orbs = Math.min(this.maxOrbs, this.orbs + n)
    this.game.hud.syncOrbs()
  }

  checkPickups(game) {
    for (const pickup of game.world.pickups) {
      if (!pickup.active) continue
      if (this.position.distanceTo(new THREE.Vector3(pickup.x, pickup.y, pickup.z)) < 1.7) {
        pickup.active = false
        pickup.group.visible = false
        if (pickup.type === 'mango') {
          this.heal(28)
          game.hud.toast('mango found', '+28 health. Sweet like September.', 'jade')
        } else if (pickup.type === 'bloom') {
          this.aether = this.maxAether
          this.game.audio.sfx('heal')
          game.hud.toast('aether bloom', 'Gauntlet fully charged.', 'jade')
        } else {
          this.addOrbs(2)
          game.hud.toast('soul cache', '+2 soul orbs.', 'jade')
        }
      }
    }
  }

  updateAimUI(game, t) {
    const hit = this.raycastAim(game, 0)
    if (hit.creature) {
      game.hud.setTarget(hit.creature, hit.dist)
      game.hud.setCrosshairDanger(hit.creature.state === 'aggro')
    } else {
      game.hud.setTarget(null)
      game.hud.setCrosshairDanger(false)
    }
  }

  updateHud(game) {
    game.hud.updateVitals({
      hp: this.hp, maxHp: this.maxHp, aether: this.aether, maxAether: this.maxAether,
      shield: this.shield, shieldMax: this.shieldMax, xp: this.xp, xpNext: this.xpNext, level: this.level,
    })
    game.hud.updateOrbRecharge(this.orbs < 3 ? this.orbRecharge / 12 : 1)
    game.hud.updateBloom(this.fireBloom, this.moving, !this.grounded)
    game.hud.updateCompanion(this.companionCooldown, this.companionCooldownMax)
  }

  cameraKick(amount) {
    this.cameraShake = Math.min(0.4, this.cameraShake + amount)
  }

  getBondSummary() {
    return this.party.map((b, i) => ({ ...b, active: i === this.activeIndex }))
  }
}

